do $$ declare name text;begin
 foreach name in array array['cw_rules','cw_rivalries','cw_windows','cw_world','cw_seasons','cw_fixture_dates','cw_club_dates','cw_clubs','cw_finance','cw_players','cw_contracts','cw_negotiations','cw_offer_history','cw_commitments','cw_news','cw_ai_days','cw_appearances','cw_stats_opening','cw_coach','cw_coach_contracts'] loop
  execute format('alter table public.%I enable row level security',name);
  execute format('revoke all on public.%I from public,anon,authenticated',name);
  if name not in('cw_rules','cw_rivalries','cw_windows') then
   execute format('drop policy if exists cw_own on public.%I',name);
   execute format('create policy cw_own on public.%I for select to authenticated using(exists(select 1 from public.careers c where c.id=career_id and c.user_id=auth.uid()))',name);
   execute format('grant select on public.%I to authenticated',name);
  end if;
 end loop;
end $$;
-- Responses are visible; the private random draw used by AI decisions is not.
revoke select on public.cw_negotiations from authenticated;
do $columns$ declare cols text;begin
 select string_agg(quote_ident(column_name),',') into cols from information_schema.columns where table_schema='public' and table_name='cw_negotiations' and column_name<>'decision_roll';
 execute 'grant select ('||cols||') on public.cw_negotiations to authenticated';
end $columns$;

create or replace function public.cw_region(p_club text)
returns text language sql stable set search_path=public as $$
 select coalesce(region,case when country in('ENG','WAL','ESP','ITA','GER','FRA','POR','NED','BEL','SCO','AUT','SUI','CZE','TUR','UKR','NOR','GRE','SVK','AZE') then 'ENG' else 'BRA' end) from public.sim_clubs where id=p_club
$$;
create or replace function public.cw_year(p_region text,p_date date)
returns int language sql immutable as $$select extract(year from p_date)::int-case when p_region='ENG' and extract(month from p_date)<7 then 1 else 0 end$$;
create or replace function public.cw_start(p_region text,p_year int)
returns date language sql immutable as $$select make_date(p_year,case when p_region='ENG' then 7 else 1 end,1)$$;
create or replace function public.cw_window_open(p_region text,p_date date)
returns boolean language sql stable security definer set search_path=public as $$
 select exists(select 1 from public.cw_windows w where w.region=p_region and p_date between make_date(extract(year from p_date)::int,w.start_month,w.start_day) and make_date(extract(year from p_date)::int,w.end_month,w.end_day))
$$;
create or replace function public.cw_next_window(p_region text,p_date date)
returns date language sql stable security definer set search_path=public as $$
 select min(make_date(extract(year from p_date)::int+y.n,w.start_month,w.start_day)) from public.cw_windows w cross join generate_series(0,1) as y(n)
 where w.region=p_region and make_date(extract(year from p_date)::int+y.n,w.start_month,w.start_day)>=p_date
$$;
create or replace function public.cw_deadline(p_date date)
returns date language sql stable security definer set search_path=public as $$select p_date+max_negotiation_days from public.cw_rules$$;
create or replace function public.cw_news_add(p_career uuid,p_key text,p_kind text,p_title text,p_body text,p_priority int default 40,p_club text default null,p_player text default null,p_season uuid default null,p_meta jsonb default '{}')
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
begin
 insert into public.cw_news(career_id,event_key,on_date,kind,title,body,priority,club_id,player_id,season_id,metadata)
 select p_career,p_key,today,p_kind,p_title,p_body,p_priority,p_club,p_player,p_season,p_meta from public.cw_world where career_id=p_career on conflict do nothing;
end $$;
create or replace function public.cw_schedule(p_season uuid)
returns int language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare n int:=0;r record;chosen date;
begin
 for r in
 select f.id,f.season_id,f.home_club,f.away_club,s.career_id,s.ends_on,
 least(s.ends_on,greatest(s.starts_on,s.starts_on+case
  when public.sim_phase(f.competition_id,f.stage)->>'type'='league' then 14+(f.round_no-1)*greatest(1,330/greatest(coalesce((c.rules->>'calendar_rounds')::int,38)-1,1))
  when public.sim_phase(f.competition_id,f.stage)->>'type' in('groups','group','swiss') then 60+(f.round_no-1)*18
  when c.kind='continental' then 210+greatest(0,public.sim_phase_index(f.competition_id,f.stage)-2)*28+greatest(coalesce(f.leg,1)-1,0)*7
  else 90+greatest(0,public.sim_phase_index(f.competition_id,f.stage)-1)*50+greatest(coalesce(f.leg,1)-1,0)*7 end)) as proposed
 from public.season_fixtures f join public.cw_seasons s on s.season_id=f.season_id join public.sim_competitions c on c.id=f.competition_id
 where f.season_id=p_season and f.status='pending' and not exists(select 1 from public.cw_fixture_dates d where d.fixture_id=f.id)
 order by exists(select 1 from public.mgr_matches m where m.fixture_id=f.id and m.status='live' and m.user_side is not null) desc,proposed,c.sort_order,f.id loop
  chosen:=case when exists(select 1 from public.mgr_matches m where m.fixture_id=r.id and m.status='live' and m.user_side is not null) then (select today from public.cw_world where career_id=r.career_id) when r.season_id=(select primary_season from public.cw_world where career_id=r.career_id) then greatest(r.proposed,(select today from public.cw_world where career_id=r.career_id)) else r.proposed end;
  while exists(select 1 from public.cw_club_dates d where d.career_id=r.career_id and d.club_id in(r.home_club,r.away_club) and d.due_on between chosen-1 and chosen+1) loop
   chosen:=chosen+1;
   if chosen>r.ends_on+45 then raise exception 'Calendário sem data válida';end if;
  end loop;
  insert into public.cw_fixture_dates values(r.id,r.season_id,r.career_id,chosen);
  insert into public.cw_club_dates values(r.career_id,r.home_club,chosen,r.id),(r.career_id,r.away_club,chosen,r.id);
  n:=n+1;
 end loop;
 return n;
end $$;
create or replace function public.cw_create_region(p_career uuid,p_region text,p_year int)
returns uuid language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare sid uuid;seq int;co record;phase jsonb;starts date;
begin
 perform 1 from public.careers where id=p_career for update;
 select season_id into sid from public.cw_seasons where career_id=p_career and region=p_region and year=p_year;
 if sid is not null then return sid;end if;
 -- Reuse legacy regional history; a completed year must never be generated twice.
 select cs.id into sid from public.career_seasons cs where cs.career_id=p_career and cs.region=p_region and cs.year=p_year and cs.mode in('coach','world') order by cs.season_no desc limit 1;
 if sid is not null then
  starts:=public.cw_start(p_region,p_year);
  insert into public.cw_seasons(career_id,region,year,season_id,starts_on,ends_on) values(p_career,p_region,p_year,sid,starts,(starts+interval '1 year - 1 day')::date);
  update public.career_seasons set was_coached=was_coached or mode='coach' where id=sid;
  if(select status from public.career_seasons where id=sid)='active' then perform public.cw_schedule(sid);end if;
  return sid;
 end if;
 if not exists(select 1 from public.sim_competitions where region=p_region and active) then raise exception 'Região sem competições cadastradas';end if;
 select coalesce(max(season_no),0)+1 into seq from public.career_seasons where career_id=p_career;
 insert into public.career_seasons(career_id,season_no,year,club_id,region,mode,day_no)
 values(p_career,seq,p_year,null,p_region,'world',coalesce((select elapsed_days from public.cw_world where career_id=p_career),0)) returning id into sid;
 perform public.mgr_init_world(p_career);perform public.cw_initialize_finances(p_career);
 starts:=public.cw_start(p_region,p_year);
 insert into public.cw_seasons(career_id,region,year,season_id,starts_on,ends_on) values(p_career,p_region,p_year,sid,starts,(starts+interval '1 year - 1 day')::date);
 perform public.sim_participants_build(sid);
 for co in select * from public.sim_competitions where region=p_region and active order by sort_order loop
  phase:=public.sim_phase_at(co.id,1);
  insert into public.season_competitions(season_id,competition_id,stage) values(sid,co.id,phase->>'id');
  perform public.sim_phase_create(sid,co.id,phase->>'id',null);
 end loop;
 perform public.cw_schedule(sid);return sid;
end $$;
create or replace function public.cw_ensure(p_career uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare s public.career_seasons;starts date;current_day date;v_region text;sid uuid;
begin
 perform 1 from public.careers where id=p_career for update;
 if exists(select 1 from public.cw_world where career_id=p_career) then return;end if;
 select * into s from public.career_seasons where career_id=p_career and mode='coach' order by season_no desc limit 1;
 if not found then raise exception 'Carreira de treinador não inicializada';end if;
 starts:=public.cw_start(s.region,s.year);
 current_day:=case when s.status='finished' then(starts+interval '1 year - 1 day')::date else least((starts+interval '1 year - 1 day')::date,starts+s.day_no*3) end;
 -- Legacy careers advanced regions sequentially. Do not move the global date behind an already completed regional year.
 select greatest(current_day,coalesce(max((public.cw_start(cs.region,cs.year)+interval '1 year - 1 day')::date),current_day)) into current_day
 from public.career_seasons cs where cs.career_id=p_career and cs.mode='coach' and (cs.status='finished' or(cs.status='archived' and not exists(select 1 from public.season_fixtures fx where fx.season_id=cs.id and fx.status='pending')));
 insert into public.cw_world(career_id,today,started_on,elapsed_days,primary_season) values(p_career,current_day,current_day,s.day_no,s.id) on conflict do nothing;
 insert into public.cw_coach(career_id,monthly_salary,contract_until) select p_career,round(70+reputation*3)::bigint,(current_day+interval '2years')::date from public.mgr_coach where career_id=p_career on conflict do nothing;
 insert into public.cw_seasons(career_id,region,year,season_id,starts_on,ends_on) values(p_career,s.region,s.year,s.id,starts,(starts+interval '1 year - 1 day')::date) on conflict do nothing;
 update public.career_seasons set was_coached=true where id=s.id;
 perform public.mgr_init_world(p_career);
 perform public.cw_initialize_finances(p_career);
 perform public.cw_schedule(s.id);
 for v_region in select distinct comp.region from public.sim_competitions comp where comp.active and comp.region<>s.region loop
  sid:=public.cw_create_region(p_career,v_region,public.cw_year(v_region,current_day));
  if(select status from public.career_seasons where id=sid)<>'active' then sid:=public.cw_create_region(p_career,v_region,public.cw_year(v_region,current_day)+1);end if;
 end loop;
 update public.season_offers set expires_on=current_day+greatest(1,coalesce(expires_day-s.day_no,7)),
 salary=coalesce(salary,150),contract_years=coalesce(contract_years,2),budget_guarantee=coalesce(budget_guarantee,0)
 where career_id=p_career and status='pending' and kind='coach' and expires_on is null;
 perform public.cw_news_add(p_career,'world:created','world','O mundo do futebol está em movimento',
 'Brasil e Europa agora seguem calendários próprios na sua carreira. Contratos, finanças e notícias evoluem com os dias.',65,s.club_id);
end $$;

-- Process bounded batches with the existing match engine. No outcome/statistic is fabricated for news.
create or replace function public.cw_simulate_due(p_career uuid,p_limit int default 24)
returns int language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare w public.cw_world;f public.season_fixtures;s public.career_seasons;co public.mgr_coach;n int:=0;m public.mgr_matches;round_due record;sid uuid;v_region text;yr int;budget int;batch_started timestamptz:=clock_timestamp();
begin
 select * into w from public.cw_world where career_id=p_career for update;
 select * into co from public.mgr_coach where career_id=p_career;
 budget:=least(greatest(p_limit,1),(select max_matches_per_batch from public.cw_rules));
 for s in select cs.* from public.career_seasons cs join public.cw_seasons ws on ws.season_id=cs.id where ws.career_id=p_career and cs.status='active' loop perform public.cw_schedule(s.id);end loop;
 for round_due in
  select fx.season_id,fx.competition_id,fx.stage,fx.round_no,min(d.due_on) as due_on
  from public.season_fixtures fx join public.cw_fixture_dates d on d.fixture_id=fx.id join public.career_seasons cs on cs.id=fx.season_id
  where d.career_id=p_career and d.due_on<=w.today and fx.status='pending' and cs.status='active'
  group by fx.season_id,fx.competition_id,fx.stage,fx.round_no
  order by min(d.due_on),fx.season_id,fx.competition_id,fx.round_no loop
  for f in select * from public.season_fixtures where season_id=round_due.season_id and competition_id=round_due.competition_id and stage=round_due.stage and round_no=round_due.round_no and status='pending' and not(season_id=w.primary_season and co.status='employed' and co.club_id in(home_club,away_club)) and exists(select 1 from public.cw_fixture_dates fd where fd.fixture_id=season_fixtures.id and fd.due_on<=w.today) order by id loop
   exit when n>=budget or clock_timestamp()-batch_started>interval '2 seconds';
   -- The existing helper handles both halves, extra time and penalties before finalizing.
   perform public.mgr_sim_fixture(f.id,p_career);
   n:=n+1;
  end loop;
  perform public.sim_advance(round_due.season_id,round_due.competition_id);
  perform public.cw_schedule(round_due.season_id);
  exit when n>=budget or clock_timestamp()-batch_started>interval '2 seconds';
 end loop;
 for s in select cs.* from public.career_seasons cs join public.cw_seasons ws on ws.season_id=cs.id where ws.career_id=p_career and cs.status='active' and cs.mode='world'
  and not exists(select 1 from public.season_fixtures f where f.season_id=cs.id and status='pending') loop
  perform public.sim_season_transition(s.id);
  update public.career_seasons set status='finished',finished_at=now(),summary=jsonb_build_object('world',true,'transition',public.sim_season_transition(s.id)) where id=s.id;
 end loop;
 -- Rollover uses the completed regional history, never a fixed team list.
 for v_region in select distinct comp.region from public.sim_competitions comp where comp.active loop
  yr:=public.cw_year(v_region,w.today);
  if not exists(select 1 from public.cw_seasons where career_id=p_career and cw_seasons.region=v_region and year=yr)
   and not exists(select 1 from public.career_seasons cs join public.cw_seasons ws on ws.season_id=cs.id where ws.career_id=p_career and ws.region=v_region and cs.status='active') then
   sid:=public.cw_create_region(p_career,v_region,yr);
  end if;
  -- Prepare the next year during the off-season, using the completed regional standings.
  if not exists(select 1 from public.career_seasons cs where cs.career_id=p_career and cs.region=v_region and cs.mode in('coach','world') and cs.status='active') then
   select greatest(yr,coalesce(max(ws.year)+1,yr)) into yr from public.cw_seasons ws where ws.career_id=p_career and ws.region=v_region;
   sid:=public.cw_create_region(p_career,v_region,yr);
  end if;
 end loop;
 update public.cw_world set needs_sync=exists(
  select 1 from public.season_fixtures fx join public.cw_fixture_dates d on d.fixture_id=fx.id join public.career_seasons cs on cs.id=fx.season_id
  where d.career_id=p_career and d.due_on<=w.today and fx.status='pending' and cs.status='active'
  and not(fx.season_id=w.primary_season and co.status='employed' and co.club_id in(fx.home_club,fx.away_club)))
 where career_id=p_career;
 return n;
end $$;

create or replace function public.cw_step_day(p_career uuid)
returns date language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare w public.cw_world;
begin
 select * into w from public.cw_world where career_id=p_career for update;
 if w.needs_sync then raise exception 'Conclua a atualização do calendário antes de avançar outro dia';end if;
 if exists(select 1 from public.mgr_matches where career_id=p_career and status='live' and user_side is not null) then raise exception 'Termine a partida em andamento';end if;
 update public.cw_world set today=today+1,elapsed_days=elapsed_days+1,last_services_on=null,needs_sync=true where career_id=p_career returning * into w;
 update public.career_seasons set day_no=w.elapsed_days where career_id=p_career and status='active' and mode in('coach','world');
 update public.mgr_players set condition=least(100,condition+4.3),rhythm=greatest(35,rhythm-.4),
  injury=case when injured_until<=w.elapsed_days then null else injury end,
  injured_until=case when injured_until<=w.elapsed_days then null else injured_until end where career_id=p_career;
 perform public.cw_finance_tick(p_career);
 perform public.cw_market_tick(p_career);
 perform public.cw_jobs_tick(p_career);
 update public.cw_world set last_services_on=w.today where career_id=p_career;
 return w.today;
end $$;
-- All helpers are private; public APIs are installed together in 29.
do $$ declare f record;begin
 for f in select p.oid::regprocedure as sig from pg_proc p join pg_namespace ns on ns.oid=p.pronamespace where ns.nspname='public' and p.proname like 'cw_%' loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.sig);
 end loop;
end $$;

create or replace function public.cw_player_value(p_career uuid,p_player text)
returns bigint language plpgsql stable security definer set search_path=public as $$
#variable_conflict use_column
declare rating numeric;age numeric;pot numeric;performance numeric:=1;
begin
 select r.rating,coalesce(cp.age_at_start,p.age,case when p.is_youth then 19 else 26 end)+coalesce(floor((w.today-w.started_on)/365.25),0),coalesce(cp.potential,r.rating)
 into rating,age,pot from public.sim_players p join public.sim_player_pos_ratings r on r.player_id=p.id and r.pos=p.position
 left join public.cw_players cp on cp.career_id=p_career and cp.player_id=p.id left join public.cw_world w on w.career_id=p_career where p.id=p_player;
 if rating is null then raise exception 'Atleta sem avaliação';end if;
 select greatest(.85,least(1.15,1+(coalesce(avg(x.rating),6.5)-6.5)*.06)) into performance from(
  select a.rating from public.cw_appearances a where a.career_id=p_career and a.player_id=p_player and a.minutes>0 order by a.on_date desc,a.fixture_id desc limit 5)x;
 return round(performance*greatest(300,power(greatest(5,rating-45),2.7)*8)*case when age<23 then 1.25 when age<29 then 1 when age<33 then .75 else .4 end*(1+greatest(0,pot-rating)*.025))::bigint;
end $$;
create or replace function public.cw_cash(p_career uuid,p_club text,p_delta bigint,p_kind text,p_ref text,p_description text,p_allow_debt boolean default false,p_meta jsonb default '{}')
returns bigint language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare account public.cw_clubs;previous public.cw_finance;shortfall bigint:=0;next_cash bigint;
begin
 select * into account from public.cw_clubs where career_id=p_career and club_id=p_club for update;
 if not found then raise exception 'Caixa do clube inexistente nesta carreira';end if;
 select * into previous from public.cw_finance where career_id=p_career and club_id=p_club and kind=p_kind and reference=p_ref;
 if found then return previous.cash_after;end if;
 next_cash:=account.cash+p_delta;
 if next_cash<0 then
  if not p_allow_debt then raise exception 'Orçamento do clube insuficiente';end if;
  shortfall:=-next_cash;next_cash:=0;
 end if;
 update public.cw_clubs set cash=next_cash,debt=debt+shortfall where career_id=p_career and club_id=p_club;
 insert into public.cw_finance(career_id,club_id,on_date,kind,amount,cash_after,reference,description,metadata)
 values(p_career,p_club,(select today from public.cw_world where career_id=p_career),p_kind,p_delta,next_cash,p_ref,p_description,p_meta||jsonb_build_object('new_debt',shortfall));
 return next_cash;
end $$;
create or replace function public.cw_reserved(p_career uuid,p_club text)
returns bigint language sql stable security definer set search_path=public as $$
 select coalesce(sum(amount),0)::bigint from public.cw_commitments where career_id=p_career and club_id=p_club and status='reserved'
$$;
create or replace function public.cw_contract_cost(p_player text,p_salary bigint,p_appearance bigint,p_goal bigint,p_role text)
returns bigint language sql stable security definer set search_path=public as $$
 select p_salary+round((case p_role when 'key' then 4 when 'starter' then 3 when 'rotation' then 1.5 else .5 end)*
 (p_appearance+p_goal*case when p.position in('ATA','PD','PE') then .35 when p.position in('MEI','MC','ME','MD') then .12 when p.position='GOL' then 0 else .03 end))::bigint
 from public.sim_players p where p.id=p_player
$$;
create or replace function public.cw_payroll(p_career uuid,p_club text)
returns bigint language sql stable security definer set search_path=public as $$
 select (select coalesce(sum(public.cw_contract_cost(player_id,monthly_salary,appearance_bonus,goal_bonus,role)),0) from public.cw_contracts where career_id=p_career and club_id=p_club and status='active')+(select coalesce(sum(monthly_salary),0) from public.cw_coach_contracts where career_id=p_career and club_id=p_club and ended_on is null and expires_on>=(select today from public.cw_world where career_id=p_career))
$$;
create or replace function public.cw_available_budget(p_career uuid,p_club text)
returns bigint language sql stable security definer set search_path=public as $$
 select case when financial_risk>=75 then 0 else greatest(0,cash-public.cw_reserved(p_career,p_club)-public.cw_payroll(p_career,p_club)*(select reserve_salary_months from public.cw_rules)-debt) end
 from public.cw_clubs where career_id=p_career and club_id=p_club
$$;
create or replace function public.cw_initialize_finances(p_career uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare w public.cw_world;
begin
 select * into w from public.cw_world where career_id=p_career;
 if not w.stats_initialized then
  insert into public.cw_stats_opening(career_id,season_id,player_id,competition_id,club_id,apps,minutes,goals,assists,rating_sum)
   select p_career,st.season_id,st.player_id,st.competition_id,st.club_id,st.apps,st.minutes,st.goals,st.assists,st.rating_sum
   from public.mgr_player_stats st join public.career_seasons cs on cs.id=st.season_id where cs.career_id=p_career on conflict do nothing;
  update public.cw_world set stats_initialized=true where career_id=p_career;
 end if;
 insert into public.cw_clubs(career_id,club_id,cash,initial_budget,monthly_revenue,prestige,strategy,fanbase)
 select p_career,c.id,round((5000+power(greatest(5,c.strength-40),3)*3)*case when public.cw_region(c.id)='ENG' then 1.8 else 1 end),
 round((5000+power(greatest(5,c.strength-40),3)*3)*case when public.cw_region(c.id)='ENG' then 1.8 else 1 end),
 round((2000+power(greatest(5,c.strength-40),2)*25)*case when public.cw_region(c.id)='ENG' then 1.5 else 1 end),
 c.strength,case abs(hashtext(c.id)::bigint)%4 when 0 then 'youth' when 1 then 'balanced' when 2 then 'ambitious' else 'sustainable' end,
 greatest(1000,(c.strength-30)*(c.strength-30)*150)
 from public.sim_clubs c on conflict do nothing;
 insert into public.cw_players(career_id,player_id,age_at_start,age_estimated,potential)
 select p_career,p.id,coalesce(p.age,case when p.is_youth then 19 else 26 end),p.age is null,
 least(99,round(r.rating)+case when coalesce(p.age,case when p.is_youth then 19 else 26 end)<23 then 12 else 3 end)
 from public.mgr_players mp join public.sim_players p on p.id=mp.player_id join public.sim_player_pos_ratings r on r.player_id=p.id and r.pos=p.position
 where mp.career_id=p_career on conflict do nothing;
 update public.cw_players set market_value=public.cw_player_value(p_career,player_id) where career_id=p_career and market_value=0;
 insert into public.cw_contracts(career_id,player_id,club_id,starts_on,expires_on,monthly_salary,role)
 select p_career,mp.player_id,mp.club_id,w.today,(w.today+make_interval(years=>1+(abs(hashtext(mp.player_id)::bigint)%4)::int))::date,
 greatest(40,round(public.cw_player_value(p_career,mp.player_id)*.0065)),case when p.is_youth then 'prospect' when r.rating>=82 then 'key' when r.rating>=74 then 'starter' else 'rotation' end
 from public.mgr_players mp join public.sim_players p on p.id=mp.player_id join public.sim_player_pos_ratings r on r.player_id=p.id and r.pos=p.position
 where mp.career_id=p_career and mp.club_id is not null and not exists(select 1 from public.cw_contracts ct where ct.career_id=p_career and ct.player_id=mp.player_id);
 update public.cw_players cp set promised_role=ct.role from public.cw_contracts ct where ct.career_id=cp.career_id and ct.player_id=cp.player_id and ct.status='active' and cp.career_id=p_career;
 insert into public.cw_finance(career_id,club_id,on_date,kind,amount,cash_after,reference,description)
 select p_career,c.club_id,w.today,'opening',c.cash,c.cash,'opening','Orçamento inicial estimado do clube' from public.cw_clubs c where c.career_id=p_career on conflict do nothing;
 insert into public.cw_coach_contracts(career_id,spell_id,club_id,starts_on,expires_on,monthly_salary)
 select p_career,c.spell_id,c.club_id,w.today,(w.today+interval '2years')::date,p.monthly_salary from public.mgr_coach c join public.cw_coach p on p.career_id=c.career_id
 where c.career_id=p_career and c.status='employed' and c.spell_id is not null on conflict do nothing;
end $$;

create or replace function public.cw_settle_month(p_career uuid,p_month date)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare month_end date:=(p_month+interval '1 month - 1 day')::date;month_days int;ct public.cw_contracts;staff public.cw_coach_contracts;club public.cw_clubs;
 due bigint;paid bigint;before_cash bigint;overlap int;ref text;apps int;goals int;revenue bigint;surplus bigint;debt_paid bigint;
begin
 perform 1 from public.careers where id=p_career for update;
 month_days:=month_end-p_month+1;
 for club in select * from public.cw_clubs where career_id=p_career order by club_id loop
  ref:=to_char(p_month,'YYYY-MM');
  select count(*) into apps from public.season_fixtures f join public.cw_fixture_dates d on d.fixture_id=f.id
   where d.career_id=p_career and f.status='played' and f.home_club=club.club_id and d.due_on between p_month and month_end;
  revenue:=club.monthly_revenue+apps*(300+club.prestige::int*12);
  perform public.cw_cash(p_career,club.club_id,revenue,'commercial',ref,'Receitas comerciais, torcida e bilheteria');
  perform public.cw_cash(p_career,club.club_id,-round(revenue*.12)::bigint,'operations',ref,'Comissão técnica e operação do clube',true);
 end loop;
 for ct in select * from public.cw_contracts where career_id=p_career and starts_on<=month_end and coalesce(ended_on,expires_on)>=p_month order by club_id,id loop
  ref:=ct.id::text||':'||to_char(p_month,'YYYY-MM');
  if exists(select 1 from public.cw_finance where career_id=p_career and club_id=ct.club_id and kind='wages' and reference=ref) then continue;end if;
  overlap:=greatest(0,least(month_end,ct.expires_on,coalesce(ct.ended_on,ct.expires_on))-greatest(p_month,ct.starts_on)+1);
  select count(*),coalesce(sum(mp.goals),0) into apps,goals from public.cw_appearances mp
   where mp.career_id=p_career and mp.player_id=ct.player_id and mp.club_id=ct.club_id and mp.minutes>0 and mp.on_date between greatest(p_month,ct.starts_on) and least(month_end,ct.expires_on,coalesce(ct.ended_on,ct.expires_on));
  due:=round(ct.monthly_salary*overlap::numeric/month_days)+apps*ct.appearance_bonus+goals*ct.goal_bonus;
  if due<=0 then continue;end if;
  select cash into before_cash from public.cw_clubs where career_id=p_career and club_id=ct.club_id;
  paid:=least(before_cash,due);
  perform public.cw_cash(p_career,ct.club_id,-due,'wages',ref,'Salário de '||public.mgr_player_name(ct.player_id),true,jsonb_build_object('contract_id',ct.id,'paid',paid,'owed',due-paid));
  update public.cw_contracts set arrears=arrears+due-paid where id=ct.id;
 end loop;
 for staff in select * from public.cw_coach_contracts where career_id=p_career and starts_on<=month_end and coalesce(ended_on,expires_on)>=p_month order by id loop
  ref:=staff.id::text||':'||to_char(p_month,'YYYY-MM');
  if exists(select 1 from public.cw_finance where career_id=p_career and club_id=staff.club_id and kind='coach_salary' and reference=ref) then continue;end if;
  overlap:=greatest(0,least(month_end,staff.expires_on,coalesce(staff.ended_on,staff.expires_on))-greatest(p_month,staff.starts_on)+1);
  due:=round(staff.monthly_salary*overlap::numeric/month_days);
  if due<=0 then continue;end if;
  select cash into before_cash from public.cw_clubs where career_id=p_career and club_id=staff.club_id;
  paid:=least(before_cash,due);
  perform public.cw_cash(p_career,staff.club_id,-due,'coach_salary',ref,'Salário do treinador',true,jsonb_build_object('paid',paid,'owed',due-paid));
  if paid>0 then perform public.econ_apply(p_career,'coins',paid::int,'coach_salary',ref);end if;
  update public.cw_coach_contracts set arrears=arrears+due-paid where id=staff.id;
 end loop;
 for club in select * from public.cw_clubs where career_id=p_career order by club_id loop
  -- Retained surpluses are recorded as club infrastructure, not unlimited cash for players.
  surplus:=greatest(0,club.cash-3*club.initial_budget);
  if surplus>0 and club.debt=0 and not exists(select 1 from public.cw_finance where career_id=p_career and club_id=club.club_id and kind='infrastructure' and reference=to_char(p_month,'YYYY-MM')) then
   perform public.cw_cash(p_career,club.club_id,-surplus,'infrastructure',to_char(p_month,'YYYY-MM'),'Investimento patrimonial da diretoria');
   update public.cw_clubs set infrastructure=infrastructure+surplus where career_id=p_career and club_id=club.club_id;
  end if;
 end loop;
end $$;

create or replace function public.cw_repay_arrears(p_career uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare c public.cw_clubs;ct public.cw_contracts;st public.cw_coach_contracts;paid bigint;ref text;d date;
begin
 select today into d from public.cw_world where career_id=p_career;
 for c in select * from public.cw_clubs where career_id=p_career and debt>0 order by club_id loop
  for ct in select * from public.cw_contracts where career_id=p_career and club_id=c.club_id and arrears>0 order by starts_on,id loop
   ref:=ct.id||':'||d;
   if exists(select 1 from public.cw_finance where career_id=p_career and club_id=c.club_id and kind='arrears' and reference=ref) then continue;end if;
   select least(cash,ct.arrears) into paid from public.cw_clubs where career_id=p_career and club_id=c.club_id;
   if paid>0 then
    perform public.cw_cash(p_career,c.club_id,-paid,'arrears',ref,'Quitação de salários atrasados');
    update public.cw_contracts set arrears=arrears-paid where id=ct.id;
    update public.cw_clubs set debt=greatest(0,debt-paid) where career_id=p_career and club_id=c.club_id;
   end if;
  end loop;
  for st in select * from public.cw_coach_contracts where career_id=p_career and club_id=c.club_id and arrears>0 order by starts_on,id loop
   ref:=st.id||':'||d;
   if exists(select 1 from public.cw_finance where career_id=p_career and club_id=c.club_id and kind='staff_arrears' and reference=ref) then continue;end if;
   select least(cash,st.arrears) into paid from public.cw_clubs where career_id=p_career and club_id=c.club_id;
   if paid>0 then
    perform public.cw_cash(p_career,c.club_id,-paid,'staff_arrears',ref,'Quitação do salário do treinador');
    perform public.econ_apply(p_career,'coins',paid::int,'coach_arrears',ref);
    update public.cw_coach_contracts set arrears=arrears-paid where id=st.id;
    update public.cw_clubs set debt=greatest(0,debt-paid) where career_id=p_career and club_id=c.club_id;
   end if;
  end loop;
  select least(debt,greatest(0,cash-public.cw_payroll(p_career,c.club_id))) into paid from public.cw_clubs where career_id=p_career and club_id=c.club_id;
  if paid>0 and not exists(select 1 from public.cw_finance where career_id=p_career and club_id=c.club_id and kind='debt_repayment' and reference=d::text) then
   perform public.cw_cash(p_career,c.club_id,-paid,'debt_repayment',d::text,'Amortização da dívida do clube');
   update public.cw_clubs set debt=greatest(0,debt-paid) where career_id=p_career and club_id=c.club_id;
  end if;
 end loop;
end $$;

create or replace function public.cw_finance_tick(p_career uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare w public.cw_world;club public.cw_clubs;coach public.mgr_coach;risk numeric;rescue bigint;ref text;ct public.cw_contracts;staff public.cw_coach_contracts;paid bigint;balance bigint;
begin
 select * into w from public.cw_world where career_id=p_career;
 if extract(day from w.today)=1 then perform public.cw_settle_month(p_career,(date_trunc('month',w.today)-interval '1month')::date);end if;
 perform public.cw_repay_arrears(p_career);
 select * into coach from public.mgr_coach where career_id=p_career;
 for club in select * from public.cw_clubs where career_id=p_career order by club_id loop
  risk:=least(100,round(100.0*club.debt/greatest(club.monthly_revenue*6,1)+case when club.cash<public.cw_payroll(p_career,club.club_id) then 25 else 0 end,2));
  update public.cw_clubs set financial_risk=risk,distress_since=case when risk>=75 then coalesce(distress_since,w.today) else null end where career_id=p_career and club_id=club.club_id;
  if risk>=75 and club.rescue_year is distinct from extract(year from w.today)::int then
   rescue:=round(club.initial_budget*(select annual_rescue_fraction from public.cw_rules));
   perform public.cw_cash(p_career,club.club_id,rescue,'recovery',extract(year from w.today)::text,'Plano limitado de recuperação financeira');
   update public.cw_clubs set debt=debt+rescue,rescue_year=extract(year from w.today)::int where career_id=p_career and club_id=club.club_id;
   perform public.cw_news_add(p_career,'recovery:'||club.club_id||':'||extract(year from w.today),'finance',public.mgr_club_name(club.club_id)||' adota recuperação financeira',
    'A diretoria limita novas contratações e oferece um plano de recuperação. O clube segue disputando suas competições.',case when coach.club_id=club.club_id then 95 else 45 end,club.club_id);
  end if;
  if coach.club_id=club.club_id and risk>=75 then
   perform public.cw_news_add(p_career,'finance-warning:'||club.club_id||':'||to_char(w.today,'IYYY-IW'),'board','A diretoria cobra responsabilidade financeira',
    'A dívida ameaça a folha salarial. Venda atletas por negociação, reduza gastos ou invista recursos. Persistir nesta situação coloca seu emprego em risco.',95,club.club_id);
   if club.distress_since is not null and w.today-club.distress_since>=45 then
    update public.mgr_coach set board_confidence=greatest(0,board_confidence-3) where career_id=p_career;
    if w.today-club.distress_since>=60 then perform public.mgr_fire(p_career,'má gestão financeira persistente');end if;
   end if;
  end if;
 end loop;
 -- Expiry is a real release; pre-contracts are registered by the market service.
 for ct in select * from public.cw_contracts where career_id=p_career and status='active' and expires_on<w.today for update loop
  update public.cw_contracts set status='expired',ended_on=expires_on where id=ct.id;
  update public.mgr_players set club_id=null where career_id=p_career and player_id=ct.player_id and club_id=ct.club_id;
  perform public.cw_prune_lineups(p_career,ct.player_id);
  perform public.cw_news_add(p_career,'expiry:'||ct.id,'contract',public.mgr_player_name(ct.player_id)||' encerra seu contrato',
   'O atleta está livre após o encerramento do vínculo com '||public.mgr_club_name(ct.club_id)||'.',case when ct.club_id=coach.club_id then 85 else 30 end,ct.club_id,ct.player_id);
 end loop;
end $$;

create or replace function public.career_club_invest(p_amount int,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;club text;previous jsonb;cash bigint;
begin
 car:=public.mgr_lock();perform public.cw_ensure(car.id);
 previous:=public.econ_request_get(car.id,p_request,'club_invest');if previous is not null then return previous;end if;
 select club_id into club from public.mgr_coach where career_id=car.id and status='employed';
 if club is null then raise exception 'Assuma um clube antes de investir';end if;
 if p_amount is null or p_amount<1 or p_amount>1000000 then raise exception 'Investimento inválido';end if;
 perform public.econ_apply(car.id,'coins',-p_amount,'club_investment',p_request::text);
 cash:=public.cw_cash(car.id,club,p_amount,'coach_investment',p_request::text,'Investimento pessoal do treinador');
 perform public.cw_news_add(car.id,'investment:'||p_request,'finance','Treinador reforça o caixa do clube',p_amount||' moedas foram transferidas da carteira pessoal para o orçamento do clube.',70,club);
 return public.econ_request_save(car.id,p_request,'club_invest',jsonb_build_object('ok',true,'club_cash',cash,'personal_coins',car.coins-p_amount));
end $$;
revoke all on function public.career_club_invest(int,uuid) from public,anon;
grant execute on function public.career_club_invest(int,uuid) to authenticated;

alter table public.cw_negotiations add column if not exists appearance_bonus bigint not null default 0;
alter table public.cw_negotiations add column if not exists goal_bonus bigint not null default 0;
create or replace function public.cw_prune_lineups(p_career uuid,p_player text)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
begin
 update public.mgr_lineups l set slots=coalesce((select jsonb_object_agg(key,value) from jsonb_each(l.slots) where value#>>'{}'<>p_player),'{}'),bench=array_remove(l.bench,p_player),updated_at=now()
 where l.career_id=p_career and l.club_id is distinct from(select club_id from public.mgr_players where career_id=p_career and player_id=p_player)
 and (l.slots::text like '%'||p_player||'%' or p_player=any(l.bench));
end $$;
create or replace function public.cw_neg_history(p_id uuid,p_actor text,p_reason text)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
begin
 insert into public.cw_offer_history(career_id,negotiation_id,on_date,actor,state,terms,explanation)
 select n.career_id,n.id,w.today,p_actor,n.status,to_jsonb(n)-'decision_roll',p_reason from public.cw_negotiations n join public.cw_world w on w.career_id=n.career_id where n.id=p_id;
end $$;
create or replace function public.cw_neg_close(p_id uuid,p_status text,p_reason text)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
begin
 update public.cw_negotiations set status=p_status,response=p_reason where id=p_id;
 update public.cw_commitments set status='released' where negotiation_id=p_id and status='reserved';
 perform public.cw_neg_history(p_id,'system',p_reason);
end $$;
create or replace function public.cw_reserve_offer(p_id uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare n public.cw_negotiations;needed bigint;available bigint;
begin
 select * into n from public.cw_negotiations where id=p_id;
 needed:=n.fee+n.signing_bonus+n.performance_bonus;
 select public.cw_available_budget(n.career_id,n.buyer_club)+coalesce((select amount from public.cw_commitments where career_id=n.career_id and reference=n.id||':offer'),0) into available;
 if needed>available then raise exception 'Orçamento livre insuficiente para taxa, luvas e bônus';end if;
 insert into public.cw_commitments(career_id,club_id,negotiation_id,kind,amount,due_on,reference)
 values(n.career_id,n.buyer_club,n.id,'offer',needed,n.expires_on,n.id||':offer')
 on conflict(career_id,club_id,reference) do update set amount=excluded.amount,status='reserved',due_on=excluded.due_on;
end $$;
create or replace function public.cw_register_transfer(p_id uuid)
returns boolean language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare n public.cw_negotiations;ct public.cw_contracts;d date;owner text;upfront bigint;part bigint;i int;own text;new_contract uuid;ref text;other record;
begin
 select * into n from public.cw_negotiations where id=p_id for update;
 if n.status='completed' then return true;end if;
 if n.status not in('agreed','precontract') then return false;end if;
 perform 1 from public.careers where id=n.career_id for update;
 select today into d from public.cw_world where career_id=n.career_id;
 if n.register_on>d then return false;end if;
 select club_id into owner from public.mgr_players where career_id=n.career_id and player_id=n.player_id for update;
 select * into ct from public.cw_contracts where career_id=n.career_id and player_id=n.player_id and status='active' for update;
 if (n.status<>'precontract' and ((n.initiator<>'renewal' and owner is distinct from n.seller_club) or ct.id is distinct from n.agreed_owner_contract)) or
    (n.status='precontract' and ct.id is not null and ct.id is distinct from n.agreed_owner_contract) then
  perform public.cw_neg_close(n.id,'cancelled','O vínculo do atleta mudou durante a negociação.');return false;
 end if;
 if n.status<>'precontract' and owner is not null and n.initiator<>'renewal' and not public.cw_window_open(public.cw_region(n.buyer_club),d) then return false;end if;
 upfront:=ceil(n.fee::numeric/n.installments)::bigint;
 if (select cash-public.cw_reserved(n.career_id,n.buyer_club)+coalesce((select amount from public.cw_commitments where career_id=n.career_id and reference=n.id||':offer'),0)-(select reserve_salary_months from public.cw_rules)*(public.cw_payroll(n.career_id,n.buyer_club)+public.cw_contract_cost(n.player_id,n.monthly_salary,n.appearance_bonus,n.goal_bonus,n.role)-coalesce(case when ct.club_id=n.buyer_club then public.cw_contract_cost(ct.player_id,ct.monthly_salary,ct.appearance_bonus,ct.goal_bonus,ct.role) else 0 end,0)) from public.cw_clubs where career_id=n.career_id and club_id=n.buyer_club)<n.fee+n.signing_bonus+n.performance_bonus then
  perform public.cw_neg_close(n.id,'failed_funds','O clube não consegue sustentar o custo e a nova folha.');return false;
 end if;
 if ct.id is not null then update public.cw_contracts set status='ended',ended_on=d-1 where id=ct.id;end if;
 update public.cw_commitments set status='released' where negotiation_id=n.id and status='reserved';
 if upfront>0 then
  perform public.cw_cash(n.career_id,n.buyer_club,-upfront,'transfer',n.id||':0','Entrada da contratação');
  if n.seller_club is not null then perform public.cw_cash(n.career_id,n.seller_club,upfront,'player_sale',n.id||':0','Receita de venda de atleta');end if;
 end if;
 if n.signing_bonus>0 then perform public.cw_cash(n.career_id,n.buyer_club,-n.signing_bonus,'player_signing',n.id::text,'Luvas do atleta');end if;
 for i in 1..n.installments-1 loop
  part:=least(upfront,n.fee-upfront*i);
  insert into public.cw_commitments(career_id,club_id,negotiation_id,kind,amount,due_on,reference)
  values(n.career_id,n.buyer_club,n.id,'installment',greatest(0,part),(d+make_interval(months=>i))::date,n.id||':installment:'||i);
 end loop;
 if n.performance_bonus>0 then
  insert into public.cw_commitments(career_id,club_id,negotiation_id,kind,amount,due_on,reference)
  values(n.career_id,n.buyer_club,n.id,'performance',n.performance_bonus,d+365,n.id||':performance');
 end if;
 insert into public.cw_contracts(career_id,player_id,club_id,starts_on,expires_on,monthly_salary,signing_bonus,appearance_bonus,goal_bonus,role)
 values(n.career_id,n.player_id,n.buyer_club,d,(d+make_interval(years=>n.contract_years))::date,n.monthly_salary,n.signing_bonus,n.appearance_bonus,n.goal_bonus,n.role) returning id into new_contract;
 update public.mgr_players set club_id=n.buyer_club where career_id=n.career_id and player_id=n.player_id;
 update public.cw_players set morale=75,promised_role=n.role,transfer_requested=false,last_warning_on=null where career_id=n.career_id and player_id=n.player_id;
 perform public.cw_prune_lineups(n.career_id,n.player_id);
 update public.cw_negotiations set status='completed',response='Contrato registrado. O atleta integra o novo elenco.',register_on=d where id=n.id;
 if n.initiator<>'renewal' then
 insert into public.mgr_transfers(career_id,season_id,player_id,from_club,to_club,kind,fee,day_no)
 select n.career_id,w.primary_season,n.player_id,n.seller_club,n.buyer_club,'transfer',n.fee::int,w.elapsed_days from public.cw_world w where w.career_id=n.career_id;
 end if;
 for other in select id from public.cw_negotiations where career_id=n.career_id and player_id=n.player_id and id<>n.id and status in('seller_review','club_pending','club_counter','player_pending','player_counter','agreed','precontract') loop
  perform public.cw_neg_close(other.id,'cancelled','O atleta assinou outro contrato.');
 end loop;
 select club_id into own from public.mgr_coach where career_id=n.career_id;
 perform public.cw_news_add(n.career_id,'transfer:'||n.id,'transfer',public.mgr_player_name(n.player_id)||case when n.initiator='renewal' then ' renova com ' else ' assina com ' end||public.mgr_club_name(n.buyer_club),
  coalesce(public.mgr_club_name(n.seller_club),'Livre no mercado')||' → '||public.mgr_club_name(n.buyer_club)||'. Valor: '||n.fee||' moedas. Contrato de '||n.contract_years||' anos.',
  case when own in(n.seller_club,n.buyer_club) then case when n.valuation>=150000 then 98 else 85 end else 45 end,n.buyer_club,n.player_id,null,
  jsonb_build_object('negotiation_id',n.id,'fee',n.fee,'from_club',n.seller_club,'to_club',n.buyer_club,'overall',(select round(rating) from public.sim_player_pos_ratings pr join public.sim_players sp on sp.id=pr.player_id and sp.position=pr.pos where sp.id=n.player_id),'position',(select position from public.sim_players where id=n.player_id),'big_signing',n.valuation>=150000 and own=n.buyer_club and n.initiator<>'renewal'));
 perform public.cw_neg_history(n.id,'system','Registro concluído com pagamentos e vínculo únicos.');return true;
end $$;
create or replace function public.cw_market_tick(p_career uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare d date;own text;n public.cw_negotiations;ct public.cw_contracts;threshold numeric;interest numeric;buyer public.cw_clubs;seller public.cw_clubs;
 r record;c public.cw_clubs;p record;id uuid;value bigint;cnt int;expected numeric;apps int;games int;new_morale numeric;paid bigint;user_region text;depth jsonb;style text;
begin
 select today into d from public.cw_world where career_id=p_career;
 if extract(doy from d)=1 then update public.cw_players set market_value=public.cw_player_value(p_career,player_id) where career_id=p_career;end if;
 select club_id into own from public.mgr_coach where career_id=p_career;
 for n in select * from public.cw_negotiations where career_id=p_career and status in('seller_review','club_pending','club_counter','player_pending','player_counter','agreed','precontract') order by created_on,id for update loop
  if n.status in('agreed','precontract') then perform public.cw_register_transfer(n.id);continue;end if;
  if n.expires_on<d then perform public.cw_neg_close(n.id,'expired','Prazo da proposta encerrado.');continue;end if;
  if n.reply_on>d or n.status in('seller_review','club_counter','player_counter') then continue;end if;
  select * into ct from public.cw_contracts where career_id=p_career and player_id=n.player_id and status='active';
  select * into buyer from public.cw_clubs where career_id=p_career and club_id=n.buyer_club;
  select * into seller from public.cw_clubs where career_id=p_career and club_id=n.seller_club;
  if n.status='club_pending' then
   select count(*) into cnt from public.mgr_players where career_id=p_career and club_id=n.seller_club;
   threshold:=n.valuation*(case when seller.financial_risk>=50 then .85 else 1.05 end)+n.valuation*case when ct.role='key' then .35 else .05 end;
   threshold:=threshold*(.9+n.decision_roll*.3)*case when ct.expires_on<d+180 then .65 else 1 end;
   if exists(select 1 from public.cw_rivalries rv where rv.club_a=least(n.buyer_club,n.seller_club) and rv.club_b=greatest(n.buyer_club,n.seller_club)) then threshold:=threshold*1.12;end if;
   threshold:=threshold*(1+least(.20,.04*(select count(*) from public.cw_negotiations z where z.career_id=p_career and z.player_id=n.player_id and z.id<>n.id and z.status in('club_pending','player_pending','seller_review'))));
   if n.seller_club is null or n.register_on>coalesce(ct.expires_on,d+999) then threshold:=0;end if;
   if (cnt<=18 and threshold>0) or n.decision_roll<.04 then
    perform public.cw_neg_close(n.id,'rejected','O clube considera o atleta indispensável ou não tem reposição.');
   elsif n.fee+n.performance_bonus*.5<threshold then
    if n.round_no>=2 or n.fee<threshold*.55 then perform public.cw_neg_close(n.id,'rejected','Os valores não atendem à avaliação do clube.');
    else
     update public.cw_negotiations set status='club_counter',fee=ceil(threshold),round_no=round_no+1,expires_on=public.cw_deadline(d),response='O clube pede uma revisão do valor.' where id=n.id;
     if n.initiator='ai' then perform public.cw_neg_close(n.id,'rejected','O comprador desistiu da contraproposta.');else perform public.cw_neg_history(n.id,'seller','Contraproposta do clube vendedor.');end if;
    end if;
   else
    update public.cw_negotiations set status='player_counter',response='Clube de acordo. Apresente salário, duração, luvas e papel ao atleta.',expires_on=public.cw_deadline(d) where id=n.id;
    if n.initiator='ai' then
     update public.cw_negotiations set status='player_pending',monthly_salary=greatest(40,ceil(coalesce(ct.monthly_salary,n.valuation*.0065)*1.15)),contract_years=3,signing_bonus=ceil(n.valuation*.02),reply_on=d+2 where id=n.id;
    end if;
    perform public.cw_neg_history(n.id,'seller','Condições entre clubes aprovadas.');
   end if;
  elsif n.status='player_pending' then
   interest:=coalesce(public.cw_contract_cost(ct.player_id,ct.monthly_salary,ct.appearance_bonus,ct.goal_bonus,ct.role),greatest(40,n.valuation*.0065))*case when buyer.prestige>=coalesce(seller.prestige,0)+5 then 1.02 else 1.12 end;
   interest:=interest*(1+greatest(0,coalesce(seller.prestige,0)-buyer.prestige)*.015);
   interest:=interest*case when (select morale from public.cw_players where career_id=p_career and player_id=n.player_id)<35 and n.initiator='renewal' then 1.35 else 1 end;
   interest:=interest*case when n.role='prospect' and coalesce(ct.role,'rotation') in('key','starter') then 1.35 else 1 end;
   if n.decision_roll<.06 and buyer.prestige<coalesce(seller.prestige,0) then
    perform public.cw_neg_close(n.id,'rejected','O atleta recusou o projeto esportivo, independentemente da remuneração.');continue;
   end if;
   if (public.cw_contract_cost(n.player_id,n.monthly_salary,n.appearance_bonus,n.goal_bonus,n.role)+n.signing_bonus/greatest(12*n.contract_years,1))<interest then
    if n.round_no>=3 or n.monthly_salary<interest*.65 then perform public.cw_neg_close(n.id,'rejected','O atleta recusou salário, papel ou projeto esportivo.');
    else update public.cw_negotiations set status='player_counter',monthly_salary=ceil(interest),round_no=round_no+1,expires_on=public.cw_deadline(d),response='O atleta pede melhores condições salariais.' where id=n.id;perform public.cw_neg_history(n.id,'player','Contraproposta salarial do atleta.');end if;
   elsif exists(select 1 from public.cw_negotiations where career_id=p_career and player_id=n.player_id and id<>n.id and status in('agreed','precontract')) then
    perform public.cw_neg_close(n.id,'rejected','O atleta já assinou um acordo.');
   else
    begin
     perform public.cw_reserve_offer(n.id);
     update public.cw_negotiations set status=case when n.register_on is not null then 'precontract' else 'agreed' end,response='Ambas as partes aprovaram. Aguardando registro.',register_on=coalesce(n.register_on,case when n.seller_club is not null and n.initiator<>'renewal' and not public.cw_window_open(public.cw_region(n.buyer_club),d) then public.cw_next_window(public.cw_region(n.buyer_club),d) else d end) where id=n.id;
     perform public.cw_neg_history(n.id,'player','Condições do atleta aprovadas.');perform public.cw_register_transfer(n.id);
    exception when raise_exception then perform public.cw_neg_close(n.id,'failed_funds',sqlerrm);end;
   end if;
  end if;
 end loop;
 -- Scheduled transfer liabilities are paid once; performance clauses require ten actual appearances.
 for r in select cm.*,n.player_id,n.seller_club,n.register_on from public.cw_commitments cm join public.cw_negotiations n on n.id=cm.negotiation_id
  where cm.career_id=p_career and cm.status='reserved' and n.status='completed' and cm.kind in('installment','performance') order by cm.due_on,cm.id loop
  if r.kind='performance' then
   select count(*) into apps from public.cw_appearances mp where mp.career_id=p_career and mp.player_id=r.player_id and mp.club_id=r.club_id and mp.minutes>0 and mp.on_date>=r.register_on;
   if apps<10 and d<r.due_on then continue;end if;
   if apps<10 then update public.cw_commitments set status='released' where id=r.id;continue;end if;
  elsif r.due_on>d then continue;end if;
  perform public.cw_cash(p_career,r.club_id,-r.amount,'transfer_clause',r.id::text,'Parcela ou bônus da contratação',true);
  if r.seller_club is not null then perform public.cw_cash(p_career,r.seller_club,r.amount,'player_sale_clause',r.id::text,'Recebimento de parcela ou bônus');end if;
  update public.cw_commitments set status='paid' where id=r.id;
 end loop;
 -- Weekly satisfaction derives from actual minutes and promises, not a daily random penalty.
 for p in select cp.*,mp.club_id,ct.arrears,ct.starts_on,ct.role from public.cw_players cp join public.mgr_players mp using(career_id,player_id)
  join public.cw_contracts ct on ct.career_id=cp.career_id and ct.player_id=cp.player_id and ct.status='active'
  where cp.career_id=p_career and (cp.last_morale_on is null or cp.last_morale_on<=d-7) loop
  if d-p.starts_on<28 then update public.cw_players set last_morale_on=d where career_id=p_career and player_id=p.player_id;continue;end if;
  select count(*) into games from public.cw_club_dates fd join public.season_fixtures f on f.id=fd.fixture_id where fd.career_id=p_career and fd.club_id=p.club_id and f.status='played' and fd.due_on between d-28 and d;
  select count(*) into apps from public.cw_appearances mp where mp.career_id=p_career and mp.player_id=p.player_id and mp.club_id=p.club_id and mp.minutes>=30 and mp.on_date between d-28 and d;
  expected:=case p.promised_role when 'key' then .75 when 'starter' then .55 when 'rotation' then .25 else .05 end;
  new_morale:=greatest(0,least(100,p.morale+case when games>=3 and apps::numeric/games<expected then -7 else 3 end-case when p.arrears>0 then 12 else 0 end));
  update public.cw_players set morale=new_morale,last_morale_on=d,transfer_requested=new_morale<30,
   last_warning_on=case when new_morale<45 then coalesce(last_warning_on,d) else null end where career_id=p_career and player_id=p.player_id;
  if new_morale<45 and p.club_id=own then perform public.cw_news_add(p_career,'morale:'||p.player_id||':'||to_char(d,'IYYY-IW'),'squad',public.mgr_player_name(p.player_id)||case when new_morale<30 then ' pede para sair' else ' cobra espaço no time' end,
   'O papel prometido, os minutos recentes e os pagamentos estão afetando a satisfação. Reveja as oportunidades e o contrato.',90,own,p.player_id);end if;
 end loop;
 -- One AI decision per club/date, with budgets and squad needs. User sales always await explicit approval.
 for c in select * from public.cw_clubs where career_id=p_career and club_id is distinct from own order by club_id loop
  insert into public.cw_ai_days values(p_career,c.club_id,d) on conflict do nothing;if not found then continue;end if;
  if not public.cw_window_open(public.cw_region(c.club_id),d) or c.financial_risk>=75 or random()>(select ai_bid_chance from public.cw_rules) then continue;end if;
  paid:=public.cw_available_budget(p_career,c.club_id);
  select coalesce(jsonb_object_agg(position,n),'{}') into depth from(select sp2.position,count(*) as n from public.mgr_players t join public.sim_players sp2 on sp2.id=t.player_id where t.career_id=p_career and t.club_id=c.club_id group by sp2.position)x;
  select a.style into style from public.mgr_ai_clubs a where a.career_id=p_career and a.club_id=c.club_id;
  select sp.id,mp.club_id,sp.position,coalesce(cp.potential,70) as potential into p from public.mgr_players mp join public.sim_players sp on sp.id=mp.player_id join public.cw_players cp on cp.career_id=mp.career_id and cp.player_id=mp.player_id
   join public.sim_player_pos_ratings pr on pr.player_id=sp.id and pr.pos=sp.position
   where mp.career_id=p_career and mp.club_id is distinct from c.club_id and sp.active
    and cp.market_value<paid*.65
    and not exists(select 1 from public.cw_negotiations x where x.career_id=p_career and x.player_id=sp.id and x.buyer_club=c.club_id and x.status in('seller_review','club_pending','club_counter','player_pending','player_counter','agreed','precontract'))
    and pr.rating>=c.prestige-12
   order by (pr.rating+case when c.strategy='youth' then cp.potential-pr.rating else 0 end)
    /greatest(1,coalesce((depth->>sp.position)::int,0))*random() +case when (style='wide' and sp.position in('PD','PE','LD','LE')) or(style='counter' and sp.position in('ATA','PD','PE')) or(style='possession' and sp.position in('MC','MEI','VOL')) then 5 else 0 end
    +case when public.cw_region(mp.club_id)<>public.cw_region(c.club_id) then 20*(select ai_foreign_preference from public.cw_rules) else 0 end desc limit 1;
  if p.id is null then continue;end if;
  select * into ct from public.cw_contracts where career_id=p_career and player_id=p.id and status='active';
  value:=public.cw_player_value(p_career,p.id);
  insert into public.cw_negotiations(career_id,player_id,seller_club,buyer_club,initiator,status,fee,monthly_salary,contract_years,signing_bonus,created_on,reply_on,expires_on,valuation,agreed_owner_contract)
   values(p_career,p.id,p.club_id,c.club_id,'ai',case when p.club_id=own then 'seller_review' else 'club_pending' end,case when p.club_id is null then 0 else round(value*(1.1+random()*.35)) end,
    greatest(40,ceil(coalesce(ct.monthly_salary,value*.0065)*1.15)),3,ceil(value*.02),d,d+2,public.cw_deadline(d),value,ct.id) returning id into id;
  begin perform public.cw_reserve_offer(id);exception when raise_exception then perform public.cw_neg_close(id,'failed_funds',sqlerrm);continue;end;
  perform public.cw_neg_history(id,'buyer','Proposta enviada pelo clube interessado.');
  if p.club_id=own then perform public.cw_news_add(p_career,'incoming:'||id,'transfer',public.mgr_club_name(c.club_id)||' faz proposta por '||public.mgr_player_name(p.id),'A venda depende da sua decisão. Abra Negociações para aceitar, recusar ou apresentar uma contraproposta.',95,own,p.id);end if;
 end loop;
 -- AI contract management: renew affordable contributors before expiry; release surplus players without deleting them.
 if extract(day from d)=15 then
  for ct in select x.* from public.cw_contracts x where x.career_id=p_career and x.status='active' and x.club_id is distinct from own and x.expires_on between d and d+120
   and not exists(select 1 from public.cw_negotiations n where n.career_id=p_career and n.player_id=x.player_id and n.status in('agreed','precontract')) loop
   if public.cw_available_budget(p_career,ct.club_id)>ct.monthly_salary*3 and (select morale from public.cw_players where career_id=p_career and player_id=ct.player_id)>=35 then
    update public.cw_contracts set status='ended',ended_on=d-1 where id=ct.id;
    insert into public.cw_contracts(career_id,player_id,club_id,starts_on,expires_on,monthly_salary,role)
     values(p_career,ct.player_id,ct.club_id,d,(d+interval '2years')::date,ceil(ct.monthly_salary*1.06),ct.role);
    perform public.cw_news_add(p_career,'ai-renew:'||ct.id,'contract',public.mgr_player_name(ct.player_id)||' renova contrato','Vínculo renovado por duas temporadas.',25,ct.club_id,ct.player_id);
   end if;
  end loop;
 end if;
end $$;

create or replace function public.career_transfer_bid(p_player text,p_fee bigint,p_installments int,p_bonus bigint,p_precontract boolean,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;own text;owner text;ct public.cw_contracts;d date;id uuid;prev jsonb;value bigint;
begin
 car:=public.mgr_lock();prev:=public.econ_request_get(car.id,p_request,'transfer_bid');if prev is not null then return prev;end if;
 select club_id into own from public.mgr_coach where career_id=car.id and status='employed';select today into d from public.cw_world where career_id=car.id;
 if own is null then raise exception 'Assuma um clube para negociar';end if;
 select club_id into owner from public.mgr_players where career_id=car.id and player_id=p_player for update;
 if not found or owner=own then raise exception 'Atleta indisponível para compra';end if;
 select * into ct from public.cw_contracts where career_id=car.id and player_id=p_player and status='active';
 if p_precontract and (ct.id is null or ct.expires_on>d+180) then raise exception 'Pré-contrato disponível apenas nos seis meses finais do vínculo';end if;
 if not p_precontract and owner is not null and not public.cw_window_open(public.cw_region(own),d) then raise exception 'Janela de transferências fechada';end if;
 if p_fee is null or p_fee not between 0 and 100000000 or p_installments is null or p_installments not between 1 and 24 or p_bonus is null or p_bonus not between 0 and 10000000 then raise exception 'Condições financeiras inválidas';end if;
 if exists(select 1 from public.cw_negotiations where career_id=car.id and player_id=p_player and buyer_club=own and status in('seller_review','club_pending','club_counter','player_pending','player_counter','agreed','precontract')) then raise exception 'Já existe uma negociação em andamento por este atleta';end if;
 value:=public.cw_player_value(car.id,p_player);
 insert into public.cw_negotiations(career_id,player_id,seller_club,buyer_club,initiator,status,fee,installments,performance_bonus,created_on,reply_on,expires_on,register_on,valuation,agreed_owner_contract)
 values(car.id,p_player,owner,own,'user',case when owner is null or p_precontract then 'player_counter' else 'club_pending' end,
 case when p_precontract or owner is null then 0 else p_fee end,p_installments,p_bonus,d,d+2,public.cw_deadline(d),case when p_precontract then ct.expires_on+1 else null end,value,ct.id) returning id into id;
 perform public.cw_reserve_offer(id);perform public.cw_neg_history(id,'user','Proposta inicial registrada.');
 return public.econ_request_save(car.id,p_request,'transfer_bid',jsonb_build_object('id',id));
end $$;
create or replace function public.career_transfer_respond(p_id uuid,p_action text,p_fee bigint,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;n public.cw_negotiations;own text;d date;prev jsonb;
begin
 car:=public.mgr_lock();prev:=public.econ_request_get(car.id,p_request,'transfer_respond');if prev is not null then return prev;end if;
 select * into n from public.cw_negotiations where id=p_id and career_id=car.id for update;if not found then raise exception 'Negociação inexistente';end if;
 select club_id into own from public.mgr_coach where career_id=car.id and status='employed';select today into d from public.cw_world where career_id=car.id;
 if own is null or (own is distinct from n.buyer_club and own is distinct from n.seller_club) or n.expires_on<d then raise exception 'Você não pode responder esta negociação';end if;
 if p_action='reject' and n.status in('seller_review','club_pending','club_counter','player_counter','player_pending') then perform public.cw_neg_close(n.id,'rejected','Proposta recusada pelo treinador.');
 elsif n.status='seller_review' and own=n.seller_club then
  if p_action='counter' then
   if n.round_no>=3 or p_fee is null or p_fee not between 0 and 100000000 then raise exception 'Contraproposta inválida';end if;
   if p_fee>n.valuation*1.8 or p_fee>public.cw_available_budget(car.id,n.buyer_club)+n.fee then perform public.cw_neg_close(n.id,'rejected','O comprador não aceita esse valor.');
   else update public.cw_negotiations set fee=p_fee,status='player_pending',reply_on=d+2,round_no=round_no+1,expires_on=public.cw_deadline(d) where id=n.id;perform public.cw_reserve_offer(n.id);end if;
  elsif p_action='accept' then update public.cw_negotiations set status='player_pending',reply_on=d+2,expires_on=public.cw_deadline(d) where id=n.id;
  else raise exception 'Resposta inválida';end if;
 elsif n.status='club_counter' and own=n.buyer_club and p_action='accept' then
  perform public.cw_reserve_offer(n.id);update public.cw_negotiations set status='player_counter',expires_on=public.cw_deadline(d),response='Clube aprovou. Negocie o contrato do atleta.' where id=n.id;
 elsif n.status='club_counter' and own=n.buyer_club and p_action='counter' then
  if n.round_no>=3 or p_fee is null or p_fee not between 0 and 100000000 then raise exception 'Contraproposta inválida';end if;
  update public.cw_negotiations set status='club_pending',fee=p_fee,round_no=round_no+1,reply_on=d+2,expires_on=public.cw_deadline(d) where id=n.id;perform public.cw_reserve_offer(n.id);
 else raise exception 'Aguarde a etapa atual da negociação';end if;
 perform public.cw_neg_history(n.id,'user','Resposta: '||p_action);
 return public.econ_request_save(car.id,p_request,'transfer_respond',jsonb_build_object('ok',true));
end $$;
create or replace function public.career_player_offer(p_id uuid,p_salary bigint,p_years int,p_signing bigint,p_role text,p_appearance bigint,p_goal bigint,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;n public.cw_negotiations;own text;prev jsonb;d date;
begin
 car:=public.mgr_lock();prev:=public.econ_request_get(car.id,p_request,'player_offer');if prev is not null then return prev;end if;
 select club_id into own from public.mgr_coach where career_id=car.id and status='employed';select today into d from public.cw_world where career_id=car.id;
 select * into n from public.cw_negotiations where id=p_id and career_id=car.id and buyer_club=own for update;
 if not found or n.status<>'player_counter' or n.expires_on<d then raise exception 'Etapa de contrato indisponível';end if;
 if p_salary is null or p_salary not between 1 and 10000000 or p_years is null or (p_years<1 or p_years>(select max_contract_years from public.cw_rules)) or p_signing is null or p_signing not between 0 and 10000000 or p_role not in('key','starter','rotation','prospect') or p_appearance is null or p_appearance not between 0 and 1000000 or p_goal is null or p_goal not between 0 and 1000000 then raise exception 'Contrato inválido';end if;
 update public.cw_negotiations set monthly_salary=p_salary,contract_years=p_years,signing_bonus=p_signing,role=p_role,appearance_bonus=p_appearance,goal_bonus=p_goal,status='player_pending',reply_on=d+2,expires_on=public.cw_deadline(d) where id=n.id;
 perform public.cw_reserve_offer(n.id);perform public.cw_neg_history(n.id,'user','Condições contratuais apresentadas ao atleta.');
 return public.econ_request_save(car.id,p_request,'player_offer',jsonb_build_object('ok',true));
end $$;
create or replace function public.career_contract_renew(p_player text,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;own text;ct public.cw_contracts;d date;id uuid;prev jsonb;
begin
 car:=public.mgr_lock();prev:=public.econ_request_get(car.id,p_request,'contract_renew');if prev is not null then return prev;end if;
 select club_id into own from public.mgr_coach where career_id=car.id and status='employed';select today into d from public.cw_world where career_id=car.id;
 select * into ct from public.cw_contracts where career_id=car.id and player_id=p_player and club_id=own and status='active';
 if not found then raise exception 'Atleta fora do seu elenco';end if;
 if exists(select 1 from public.cw_negotiations where career_id=car.id and player_id=p_player and status in('agreed','precontract')) then raise exception 'O atleta já tem compromisso firmado';end if;
 insert into public.cw_negotiations(career_id,player_id,seller_club,buyer_club,initiator,status,fee,monthly_salary,contract_years,role,created_on,reply_on,expires_on,valuation,agreed_owner_contract)
 values(car.id,p_player,null,own,'renewal','player_counter',0,ceil(ct.monthly_salary*1.08),2,ct.role,d,d,public.cw_deadline(d),public.cw_player_value(car.id,p_player),ct.id) returning id into id;
 perform public.cw_neg_history(id,'user','Renovação aberta. Apresente as novas condições.');
 return public.econ_request_save(car.id,p_request,'contract_renew',jsonb_build_object('id',id));
end $$;
create or replace function public.career_player_role(p_player text,p_role text)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;own text;
begin
 car:=public.mgr_lock();select club_id into own from public.mgr_coach where career_id=car.id and status='employed';
 if p_role not in('key','starter','rotation','prospect') or not exists(select 1 from public.mgr_players where career_id=car.id and player_id=p_player and club_id=own) then raise exception 'Papel ou atleta inválido';end if;
 update public.cw_players set promised_role=p_role where career_id=car.id and player_id=p_player;
 return jsonb_build_object('ok',true);
end $$;

-- Preserve mature board/objective calculations; add contract and credibility effects around them.
do $$begin
 if to_regprocedure('public.mgr_fire_before_world(uuid,text)') is null then alter function public.mgr_fire(uuid,text) rename to mgr_fire_before_world;end if;
 if to_regprocedure('public.mgr_end_spell_before_world(uuid,text)') is null then alter function public.mgr_end_spell(uuid,text) rename to mgr_end_spell_before_world;end if;
 if to_regprocedure('public.mgr_make_offer_before_world(uuid,uuid,integer,boolean,boolean)') is null then alter function public.mgr_make_offer(uuid,uuid,int,boolean,boolean) rename to mgr_make_offer_before_world;end if;
end $$;
create or replace function public.mgr_end_spell(p_career uuid,p_reason text)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
begin
 update public.cw_coach_contracts set ended_on=(select today-1 from public.cw_world where career_id=p_career)
 where career_id=p_career and ended_on is null and spell_id=(select spell_id from public.mgr_coach where career_id=p_career);
 perform public.mgr_end_spell_before_world(p_career,p_reason);
end $$;
create or replace function public.mgr_fire(p_career uuid,p_reason text)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare c public.mgr_coach;financial boolean:=p_reason ilike '%financeir%';
begin
 select * into c from public.mgr_coach where career_id=p_career;
 if c.status<>'employed' then return;end if;
 perform public.mgr_fire_before_world(p_career,p_reason);
 update public.cw_coach set credibility=greatest(0,credibility-case when financial then 22 else 9 end),financial_dismissals=financial_dismissals+case when financial then 1 else 0 end where career_id=p_career;
 perform public.cw_news_add(p_career,'dismissal:'||c.spell_id,'job','Diretoria encerra o contrato do treinador',
  public.mgr_club_name(c.club_id)||': '||p_reason||'. A credibilidade e o acesso a novas propostas foram afetados.',100,c.club_id);
end $$;
create or replace function public.mgr_make_offer(p_career uuid,p_season uuid,p_day int,p_force_weak boolean default false,p_any_region boolean default false)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare result jsonb;oid uuid;d date;cred numeric;club text;pay bigint;budget bigint;bonus int;
begin
 if not exists(select 1 from public.cw_world where career_id=p_career) then return public.mgr_make_offer_before_world(p_career,p_season,p_day,p_force_weak,p_any_region);end if;
 select credibility into cred from public.cw_coach where career_id=p_career;
 -- A financial dismissal reduces the reach of the next search, including forced low-tier searches.
 result:=public.mgr_make_offer_before_world(p_career,p_season,p_day,p_force_weak or cred<45,true);
 if result is null then return null;end if;
 oid:=(result->>'id')::uuid;club:=result->>'club_id';select today into d from public.cw_world where career_id=p_career;
 if (select prestige from public.cw_clubs where career_id=p_career and club_id=club)>55+(select reputation from public.mgr_coach where career_id=p_career)*.32+(cred-65)*.18 then
  update public.season_offers set status='expired',responded_at=now() where id=oid;return null;
 end if;
 pay:=greatest(70,round((select prestige from public.cw_clubs where career_id=p_career and club_id=club)*2.5+cred));
 budget:=greatest(0,public.cw_available_budget(p_career,club));
 select least(bonus_coins,greatest(0,budget/50)::int) into bonus from public.season_offers where id=oid;
 budget:=greatest(0,budget-bonus-2*pay);
 update public.season_offers set salary=pay,contract_years=2,budget_guarantee=budget,expires_on=public.cw_deadline(d),expires_day=p_day+(select max_negotiation_days from public.cw_rules),
 bonus_coins=bonus,pitch=replace(pitch,'na próxima temporada','na temporada em andamento') where id=oid;
 perform public.cw_news_add(p_career,'job-offer:'||oid,'job',public.mgr_club_name(club)||' procura novo treinador','Proposta de contrato por duas temporadas. Salário e orçamento podem ser negociados em Carreira.',95,club);
 return result||jsonb_build_object('salary',pay,'contract_years',2,'budget_guarantee',budget,'expires_on',public.cw_deadline(d));
end $$;
create or replace function public.cw_jobs_tick(p_career uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare w public.cw_world;c public.mgr_coach;off jsonb;wait_days int;
begin
 select * into w from public.cw_world where career_id=p_career;select * into c from public.mgr_coach where career_id=p_career;
 update public.season_offers set status='expired',responded_at=now() where career_id=p_career and kind='coach' and status='pending' and expires_on<w.today;
 wait_days:=w.elapsed_days-coalesce(c.unemployed_day,w.elapsed_days);
 if (select count(*) from public.season_offers where career_id=p_career and kind='coach' and status='pending')<3 and
 ((c.status='unemployed' and (random()<.10+c.reputation*.003 or wait_days>=10)) or (c.status='employed' and random()<.004+c.reputation*.00015)) then
  off:=public.mgr_make_offer(p_career,w.primary_season,w.elapsed_days,c.status='unemployed' and wait_days>=10,true);
 end if;
 if c.status='employed' and (select contract_until from public.cw_coach where career_id=p_career)<w.today then
  perform public.mgr_end_spell(p_career,'expired');
  perform public.cw_news_add(p_career,'coach-expired:'||c.spell_id,'job','Contrato do treinador encerrado','O vínculo com '||public.mgr_club_name(c.club_id)||' chegou ao fim. Você está disponível para novas propostas.',100,c.club_id);
 end if;
 if c.status='employed' and (select contract_until from public.cw_coach where career_id=p_career) between w.today and w.today+60 then
  perform public.cw_news_add(p_career,'coach-renew:'||c.spell_id,'contract','Seu contrato entra nos meses finais','Negocie a renovação em Carreira antes do encerramento do vínculo.',95,c.club_id);
 end if;
end $$;
create or replace function public.career_job_negotiate(p_offer uuid,p_salary bigint,p_years int,p_budget bigint,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;o public.season_offers;prev jsonb;limit_salary bigint;available bigint;
begin
 car:=public.mgr_lock();prev:=public.econ_request_get(car.id,p_request,'job_negotiate');if prev is not null then return prev;end if;
 select * into o from public.season_offers where id=p_offer and career_id=car.id and kind='coach' and status='pending' for update;
 if not found or o.expires_on<(select today from public.cw_world where career_id=car.id) or o.negotiation_round>=2 then raise exception 'Negociação de emprego indisponível';end if;
 if p_salary is null or p_salary not between 1 and 100000 or p_years is null or p_years not between 1 and 5 or p_budget is null or p_budget not between 0 and 100000000 then raise exception 'Condições de emprego inválidas';end if;
 limit_salary:=round(o.salary*(1.12+(select reputation from public.mgr_coach where career_id=car.id)/1000));available:=greatest(0,public.cw_available_budget(car.id,o.from_club)-o.bonus_coins-2*p_salary);
 if p_salary>limit_salary*1.3 or p_budget>available or p_years>3 then
  update public.season_offers set salary=limit_salary,contract_years=2,budget_guarantee=greatest(0,public.cw_available_budget(car.id,o.from_club)-o.bonus_coins-2*limit_salary),negotiation_round=negotiation_round+1,pitch='A diretoria apresentou sua contraproposta. O caixa limita o orçamento prometido.' where id=o.id;
 else update public.season_offers set salary=p_salary,contract_years=p_years,budget_guarantee=p_budget,negotiation_round=negotiation_round+1,pitch='A diretoria aprovou os termos negociados. O contrato está pronto para assinatura.' where id=o.id;end if;
 return public.econ_request_save(car.id,p_request,'job_negotiate',jsonb_build_object('ok',true));
end $$;
create or replace function public.career_coach_renew(p_years int,p_salary bigint,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;c public.mgr_coach;d date;until_date date;prev jsonb;
begin
 car:=public.mgr_lock();prev:=public.econ_request_get(car.id,p_request,'coach_renew');if prev is not null then return prev;end if;
 select * into c from public.mgr_coach where career_id=car.id;select today into d from public.cw_world where career_id=car.id;
 if c.status<>'employed' or c.board_confidence<45 or p_years is null or p_years not between 1 and 3 or p_salary is null or p_salary<1 or p_salary>(select monthly_salary*1.2 from public.cw_coach where career_id=car.id) or (select financial_risk from public.cw_clubs where career_id=car.id and club_id=c.club_id)>=75 then raise exception 'A diretoria não aceita estas condições de renovação';end if;
 until_date:=((select greatest(contract_until,d) from public.cw_coach where career_id=car.id)+make_interval(years=>p_years))::date;
 if until_date>(d+interval '5 years')::date then raise exception 'O prazo total do vínculo não pode superar cinco anos';end if;
 -- Keep the old salary immutable: renew salary after the current contract ends, or extend at the existing salary.
 if p_salary<>(select monthly_salary from public.cw_coach where career_id=car.id) then raise exception 'A renovação antecipada mantém o salário atual';end if;
 update public.cw_coach set contract_until=until_date where career_id=car.id;
 update public.cw_coach_contracts set expires_on=until_date where career_id=car.id and spell_id=c.spell_id and ended_on is null;
 perform public.cw_news_add(car.id,'coach-renewed:'||p_request,'job','Diretoria renova com o treinador','Novo prazo contratual: '||until_date||'.',90,c.club_id);
 return public.econ_request_save(car.id,p_request,'coach_renew',jsonb_build_object('ok',true));
end $$;
create or replace function public.cw_archive_match()
returns trigger language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
begin
 if new.status<>'finished' or old.status='finished' or not exists(select 1 from public.cw_world where career_id=new.career_id) then return new;end if;
 insert into public.cw_appearances(career_id,fixture_id,season_id,competition_id,player_id,club_id,on_date,minutes,goals,assists,rating,starter)
 select new.career_id,new.fixture_id,new.season_id,f.competition_id,mp.player_id,mp.club_id,coalesce(fd.due_on,w.today),mp.minutes,mp.goals,mp.assists,mp.rating,mp.starter
 from public.mgr_match_players mp join public.season_fixtures f on f.id=mp.fixture_id join public.cw_world w on w.career_id=new.career_id left join public.cw_fixture_dates fd on fd.fixture_id=f.id
 where mp.fixture_id=new.fixture_id and mp.minutes>0 on conflict do nothing;
 return new;
end $$;
drop trigger if exists cw_archive_match_trg on public.mgr_matches;
create trigger cw_archive_match_trg after update of status on public.mgr_matches for each row execute function public.cw_archive_match();

-- Competition awards are derived from stored final tables and individual match statistics.
create or replace function public.cw_competition_news()
returns trigger language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare s public.career_seasons;co public.sim_competitions;mvp record;runner text;scorer record;
begin
 if new.status<>'finished' or (tg_op='UPDATE' and old.status='finished') then return new;end if;
 select * into s from public.career_seasons where id=new.season_id;
 if not exists(select 1 from public.cw_world where career_id=s.career_id) then return new;end if;
 select * into co from public.sim_competitions where id=new.competition_id;
 runner:=new.runner_up_club;
 if co.kind='league' then select club_id into runner from public.sim_standings(s.id,co.id,null) where pos=2;end if;
 with contributions as (
  select a.player_id,a.club_id,count(*)::int as apps,sum(a.goals)::int as goals,sum(a.assists)::int as assists,sum(a.rating) as rating_sum
   from public.cw_appearances a where a.season_id=s.id and a.competition_id=co.id and a.minutes>0 group by a.player_id,a.club_id
  union all
  select st.player_id,st.club_id,st.apps,st.goals,st.assists,st.rating_sum from public.cw_stats_opening st where st.season_id=s.id and st.competition_id=co.id
 ), scores as (
  select player_id,club_id,sum(apps)::int as apps,sum(goals)::int as goals,sum(assists)::int as assists,round(sum(rating_sum)/greatest(sum(apps),1),2) as rating from contributions
  where club_id=new.champion_club group by player_id,club_id
 ) select * into mvp from scores where apps>=greatest(1,(select max(apps)/3 from scores)) order by rating desc,goals desc,assists desc,player_id limit 1;
 select st.player_id,sum(st.goals)::int as goals into scorer from public.mgr_player_stats st where st.season_id=s.id and st.competition_id=co.id group by st.player_id order by sum(st.goals) desc,sum(st.assists) desc,st.player_id limit 1;
 perform public.cw_news_add(s.career_id,'champion:'||s.id||':'||co.id,'title',public.mgr_club_name(new.champion_club)||' conquista '||co.name,
 'Campeão: '||public.mgr_club_name(new.champion_club)||coalesce('. Vice: '||public.mgr_club_name(runner),'')||coalesce('. Melhor atleta da equipe campeã: '||public.mgr_player_name(mvp.player_id)||' (nota '||mvp.rating||')','')||case when scorer.goals>0 then '. Artilheiro: '||public.mgr_player_name(scorer.player_id)||' ('||scorer.goals||' gols)' else '' end||'.',85,new.champion_club,mvp.player_id,s.id,
 jsonb_build_object('competition',co.id,'champion',new.champion_club,'runner_up',runner,'mvp',to_jsonb(mvp),'top_scorer',to_jsonb(scorer)));
 perform public.cw_cash(s.career_id,new.champion_club,case when co.kind='continental' then 30000 when co.kind='league' then 20000 else 10000 end,'competition_prize',s.id||':'||co.id,'Premiação por título: '||co.name);
 if runner is not null then perform public.cw_cash(s.career_id,runner,case when co.kind='continental' then 15000 when co.kind='league' then 10000 else 5000 end,'competition_runner',s.id||':'||co.id,'Premiação por vice: '||co.name);end if;
 if new.champion_club=(select club_id from public.mgr_coach where career_id=s.career_id) and s.id=(select primary_season from public.cw_world where career_id=s.career_id) then update public.cw_coach set credibility=least(100,credibility+4) where career_id=s.career_id;end if;
 return new;
end $$;
drop trigger if exists cw_competition_news_trg on public.season_competitions;
create trigger cw_competition_news_trg after insert or update of status on public.season_competitions for each row execute function public.cw_competition_news();
create or replace function public.cw_result_news()
returns trigger language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare c uuid;winner text;loser text;diff numeric;previous int;sc public.sim_competitions;leader record;second_team record;
begin
 if new.status<>'played' or (tg_op='UPDATE' and old.status='played') then return new;end if;
 select career_id into c from public.career_seasons where id=new.season_id;
 if not exists(select 1 from public.cw_world where career_id=c) then return new;end if;
 select * into sc from public.sim_competitions where id=new.competition_id;
 winner:=case when new.home_goals>new.away_goals then new.home_club when new.away_goals>new.home_goals then new.away_club else new.tie_winner end;
 loser:=case when winner=new.home_club then new.away_club when winner=new.away_club then new.home_club end;
 select b.strength-a.strength into diff from public.sim_clubs a,public.sim_clubs b where a.id=winner and b.id=loser;
 if diff>=12 then perform public.cw_news_add(c,'upset:'||new.id,'result',public.mgr_club_name(winner)||' surpreende favorito',new.home_goals||' × '||new.away_goals||': '||public.mgr_club_name(new.home_club)||' e '||public.mgr_club_name(new.away_club)||'.',65,winner,null,new.season_id,jsonb_build_object('fixture_id',new.id));end if;
 if new.tie_winner is not null and new.stage not in('league','group','swiss') then perform public.cw_news_add(c,'knockout:'||new.id,'result',public.mgr_club_name(new.tie_winner)||' avança de fase',public.mgr_club_name(loser)||' deixa a disputa de '||sc.name||'.',60,new.tie_winner,null,new.season_id,jsonb_build_object('fixture_id',new.id));end if;
 if new.player_match then perform public.cw_news_add(c,'user-result:'||new.id,'result',public.mgr_club_name(new.home_club)||' '||new.home_goals||' × '||new.away_goals||' '||public.mgr_club_name(new.away_club),sc.name||' · Rodada '||new.round_no||'.',90,new.coach_club,null,new.season_id,jsonb_build_object('fixture_id',new.id));end if;
 if sc.kind='league' and new.round_no>=8 and not exists(select 1 from public.season_fixtures fx where fx.season_id=new.season_id and fx.competition_id=new.competition_id and fx.round_no=new.round_no and fx.status='pending') then
  select * into leader from public.sim_standings(new.season_id,new.competition_id,null) where pos=1;
  select * into second_team from public.sim_standings(new.season_id,new.competition_id,null) where pos=2;
  if leader.points-second_team.points<=2 then perform public.cw_news_add(c,'race:'||new.season_id||':'||sc.id||':'||new.round_no,'race','Disputa pela liderança de '||sc.name,
   public.mgr_club_name(leader.club_id)||' e '||public.mgr_club_name(second_team.club_id)||' terminaram a rodada '||new.round_no||' separados por até dois pontos.',50,leader.club_id,null,new.season_id);end if;
 end if;
 select max(abs(f.home_goals-f.away_goals)) into previous from public.season_fixtures f join public.career_seasons s on s.id=f.season_id where s.career_id=c and f.status='played' and f.id<>new.id;
 if abs(new.home_goals-new.away_goals)>greatest(coalesce(previous,0),4) then perform public.cw_news_add(c,'record:'||new.id,'record','Maior goleada desta carreira',public.mgr_club_name(new.home_club)||' '||new.home_goals||' × '||new.away_goals||' '||public.mgr_club_name(new.away_club)||'. Recorde entre as partidas já disputadas nesta carreira.',75,winner,null,new.season_id);end if;
 return new;
end $$;
drop trigger if exists cw_result_news_trg on public.season_fixtures;
create trigger cw_result_news_trg after insert or update of status on public.season_fixtures for each row execute function public.cw_result_news();

do $$begin
 if to_regprocedure('public.mgr_sync_base_cards_before_world(uuid)') is null then alter function public.mgr_sync_base_cards(uuid) rename to mgr_sync_base_cards_before_world;end if;
 if to_regprocedure('public.mgr_hub_before_world()') is null then alter function public.mgr_hub() rename to mgr_hub_before_world;end if;
 if to_regprocedure('public.mgr_match_start_before_world()') is null then alter function public.mgr_match_start() rename to mgr_match_start_before_world;end if;
 if to_regprocedure('public.mgr_new_season_before_world(uuid)') is null then alter function public.mgr_new_season(uuid) rename to mgr_new_season_before_world;end if;
 if to_regprocedure('public.mgr_match_create_before_world(bigint,uuid,character,jsonb)') is null then alter function public.mgr_match_create(bigint,uuid,char,jsonb) rename to mgr_match_create_before_world;end if;
 if to_regprocedure('public.sim_next_event_before_world(uuid,text)') is null then alter function public.sim_next_event(uuid,text) rename to sim_next_event_before_world;end if;
end $$;
create or replace function public.mgr_sync_base_cards(p_career uuid)
returns int language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
begin
 if exists(select 1 from public.cw_world where career_id=p_career) then return 0;end if;
 return public.mgr_sync_base_cards_before_world(p_career);
end $$;
create or replace function public.mgr_lock()
returns public.careers language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare c public.careers;
begin
 c:=public.sim_lock_career();perform public.mgr_ensure(c);perform public.mgr_sync_base_cards(c.id);perform public.cw_ensure(c.id);
 if not(select stats_initialized from public.cw_world where career_id=c.id) then perform public.cw_initialize_finances(c.id);end if;
 update public.season_offers set status='expired',responded_at=now() where career_id=c.id and kind='coach' and status='pending' and expires_on<(select today from public.cw_world where career_id=c.id);
 select * into c from public.careers where id=c.id;return c;
end $$;
create or replace function public.sim_next_event(p_season uuid,p_club text)
returns table(o_comp text,o_kind text,o_stage text,o_round int)
language sql stable security definer set search_path=public as $$
 select * from public.sim_next_event_before_world(p_season,p_club) where not exists(select 1 from public.cw_seasons where season_id=p_season)
 union all
 (select f.competition_id,case when p_club in(f.home_club,f.away_club) then 'mine' else 'free' end,f.stage,f.round_no
 from public.season_fixtures f join public.cw_fixture_dates d on d.fixture_id=f.id
 where f.season_id=p_season and f.status='pending'
 order by d.due_on,(p_club in(f.home_club,f.away_club)) desc nulls last,f.id limit 1)
$$;
create or replace function public.mgr_match_create(p_fixture bigint,p_career uuid,p_user_side char,p_user_lineup jsonb)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare v_side text;factor numeric;club text;due date;previous_day date;recovery int;
begin
 if exists(select 1 from public.mgr_matches where fixture_id=p_fixture) then return;end if;
 if p_user_side is null and exists(select 1 from public.cw_world where career_id=p_career) then
  select due_on into due from public.cw_fixture_dates where fixture_id=p_fixture;
  if due<(select started_on from public.cw_world where career_id=p_career) then
  for club in select home_club from public.season_fixtures where id=p_fixture union all select away_club from public.season_fixtures where id=p_fixture loop
   select max(fd.due_on) into previous_day from public.cw_fixture_dates fd join public.season_fixtures fx on fx.id=fd.fixture_id where fd.career_id=p_career and fx.status='played' and club in(fx.home_club,fx.away_club) and fd.due_on<due;
   recovery:=greatest(0,least(14,coalesce(due-previous_day,3)));
   update public.mgr_players set condition=least(100,condition+recovery*4.3),
    injury=case when injured_until-recovery<=(select elapsed_days from public.cw_world where career_id=p_career) then null else injury end,
    injured_until=case when injured_until-recovery<=(select elapsed_days from public.cw_world where career_id=p_career) then null else injured_until-recovery end
    where career_id=p_career and club_id=club;
  end loop;
  end if;
 end if;
 perform public.mgr_match_create_before_world(p_fixture,p_career,p_user_side,p_user_lineup);
 if exists(select 1 from public.cw_world where career_id=p_career) then
  foreach v_side in array array['h','a'] loop
   select .90+coalesce(avg(cp.morale),65)/1000 into factor from public.mgr_match_players mp join public.cw_players cp on cp.career_id=p_career and cp.player_id=mp.player_id where mp.fixture_id=p_fixture and mp.side=v_side and mp.status='on';
   update public.mgr_matches set state=jsonb_set(state,array['form',case when v_side='h' then '0' else '1' end],to_jsonb(round((state->'form'->>case when v_side='h' then 0 else 1 end)::numeric*factor,3))) where fixture_id=p_fixture;
  end loop;
 end if;
end $$;
create or replace function public.mgr_match_start()
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare c public.careers;due date;
begin
 c:=public.mgr_lock();
 if not exists(select 1 from public.mgr_matches where career_id=c.id and status='live' and user_side is not null) then
  if(select needs_sync from public.cw_world where career_id=c.id) then raise exception 'Atualize os resultados do mundo antes de jogar';end if;
  select min(d.due_on) into due from public.cw_fixture_dates d join public.season_fixtures f on f.id=d.fixture_id join public.cw_world w on w.primary_season=f.season_id join public.mgr_coach co on co.career_id=w.career_id
   where w.career_id=c.id and f.status='pending' and co.club_id in(f.home_club,f.away_club);
  if due>(select today from public.cw_world where career_id=c.id) then raise exception 'Avance o calendário até a data da partida';end if;
 end if;
 return public.mgr_match_start_before_world();
end $$;
create or replace function public.sim_play_round(p_season uuid,p_comp text,p_stage text,p_round int)
returns int language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare s public.career_seasons;r record;n int:=0;
begin
 select * into s from public.career_seasons where id=p_season;
 for r in select f.id from public.season_fixtures f left join public.cw_fixture_dates d on d.fixture_id=f.id
  where f.season_id=p_season and f.competition_id=p_comp and f.stage=p_stage and f.round_no=p_round and f.status='pending'
  and (not exists(select 1 from public.cw_world where career_id=s.career_id) or d.due_on<=(select today from public.cw_world where career_id=s.career_id)) order by f.id loop
  perform public.mgr_sim_fixture(r.id,s.career_id);n:=n+1;
 end loop;return n;
end $$;
create or replace function public.mgr_day_tick(p_career uuid,p_season uuid)
returns int language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
begin
 perform public.cw_schedule(p_season);perform public.cw_simulate_due(p_career,24);
 if not(select needs_sync from public.cw_world where career_id=p_career) then perform public.cw_step_day(p_career);end if;
 return(select elapsed_days from public.cw_world where career_id=p_career);
end $$;
create or replace function public.career_world_advance(p_days int,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;w public.cw_world;c public.mgr_coach;prev jsonb;days int:=0;n int:=0;t timestamptz:=clock_timestamp();sid uuid;summary jsonb;stopped boolean;ready boolean;s public.career_seasons;
begin
 car:=public.mgr_lock();prev:=public.econ_request_get(car.id,p_request,'world_advance');if prev is not null then return prev;end if;
 if p_days is null or (p_days<0 or p_days>(select max_days_per_call from public.cw_rules)) then raise exception 'Quantidade de dias acima do limite por atualização';end if;
 if exists(select 1 from public.mgr_matches where career_id=car.id and status='live' and user_side is not null) then raise exception 'Termine a partida em andamento';end if;
 loop
  n:=n+public.cw_simulate_due(car.id,24);select * into w from public.cw_world where career_id=car.id;select * into c from public.mgr_coach where career_id=car.id;
  select * into s from public.career_seasons where id=w.primary_season;
  exit when w.needs_sync or days>=p_days or clock_timestamp()-t>interval '3seconds';
  exit when s.status='finished' and w.today>=public.cw_start(s.region,s.year+1);
  exit when exists(select 1 from public.season_fixtures f join public.cw_fixture_dates fd on fd.fixture_id=f.id where f.season_id=w.primary_season and f.status='pending' and c.club_id in(f.home_club,f.away_club) and fd.due_on<=w.today);
  perform public.cw_step_day(car.id);days:=days+1;
 end loop;
 if not exists(select 1 from public.season_fixtures where season_id=w.primary_season and status='pending') and(select status from public.career_seasons where id=w.primary_season)='active' then summary:=public.mgr_season_end(w.primary_season);end if;
 select exists(select 1 from public.season_fixtures f join public.cw_fixture_dates fd on fd.fixture_id=f.id where f.season_id=w.primary_season and f.status='pending' and c.club_id in(f.home_club,f.away_club) and fd.due_on<=w.today) into stopped;
 select cs.status='finished' and w.today>=public.cw_start(cs.region,cs.year+1) into ready from public.career_seasons cs where cs.id=w.primary_season;
 return public.econ_request_save(car.id,p_request,'world_advance',jsonb_build_object('today',w.today,'days',days,'days_remaining',greatest(0,p_days-days),'stopped_for_match',stopped,'next_season_ready',ready,'matches',n,'more',w.needs_sync,'rounds','[]'::jsonb,'offers','[]'::jsonb,'season_finished',summary is not null,'season_summary',summary));
end $$;
create or replace function public.mgr_advance(p_until_offer boolean default false)
returns jsonb language sql security definer set search_path=public as $$select public.career_world_advance(least(case when p_until_offer then 14 else 7 end,(select max_days_per_call from public.cw_rules)),gen_random_uuid())$$;
create or replace function public.cw_promote_season(p_career uuid,p_season uuid,p_club text)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare seq int;old_id uuid;
begin
 select primary_season into old_id from public.cw_world where career_id=p_career;
 if not exists(select 1 from public.career_seasons where id=p_season and career_id=p_career and status='active') then raise exception 'Temporada regional ainda indisponível; atualize o mundo';end if;
 if old_id is distinct from p_season then
  update public.career_seasons set mode='world',club_id=case when status='active' then null else club_id end where id=old_id;
  select max(season_no)+1 into seq from public.career_seasons where career_id=p_career;
  update public.career_seasons set mode='coach',was_coached=true,club_id=p_club,season_no=seq where id=p_season;
  update public.cw_world set primary_season=p_season,needs_sync=true where career_id=p_career;
 else update public.career_seasons set club_id=p_club,mode='coach',was_coached=true where id=p_season;end if;
end $$;
create or replace function public.mgr_offer_region_ok(p_career uuid,p_club text)
returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.cw_seasons ws join public.career_seasons s on s.id=ws.season_id join public.cw_world w on w.career_id=ws.career_id where ws.career_id=p_career and ws.region=public.cw_region(p_club) and s.status='active')$$;
create or replace function public.mgr_offer_respond(p_offer uuid,p_accept boolean)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;o public.season_offers;c public.mgr_coach;w public.cw_world;sid uuid;spell uuid;
begin
 car:=public.mgr_lock();select * into w from public.cw_world where career_id=car.id;
 select * into o from public.season_offers where id=p_offer and career_id=car.id and kind='coach' for update;
 if not found then raise exception 'Proposta inexistente';end if;
 if o.status='accepted' and p_accept then return jsonb_build_object('ok',true,'accepted',true,'club_id',o.from_club);end if;
 if o.status<>'pending' or o.expires_on<w.today then raise exception 'Proposta encerrada';end if;
 if exists(select 1 from public.mgr_matches where career_id=car.id and status='live' and user_side is not null) then raise exception 'Termine a partida em andamento';end if;
 if p_accept then
  if w.needs_sync then raise exception 'Atualize os resultados do mundo antes de trocar de clube';end if;
  select ws.season_id into sid from public.cw_seasons ws join public.career_seasons s on s.id=ws.season_id where ws.career_id=car.id and ws.region=public.cw_region(o.from_club) and s.status='active' order by ws.starts_on limit 1;
  if sid is null then raise exception 'Atualize o calendário regional antes de assumir o clube';end if;
  if (select cash-public.cw_reserved(car.id,o.from_club) from public.cw_clubs where career_id=car.id and club_id=o.from_club)<coalesce(o.bonus_coins,0)+2*o.salary or greatest(0,public.cw_available_budget(car.id,o.from_club)-coalesce(o.bonus_coins,0)-2*o.salary)<coalesce(o.budget_guarantee,0) then raise exception 'O clube não pode sustentar os termos do contrato';end if;
  select * into c from public.mgr_coach where career_id=car.id;
  if c.status='employed' then perform public.mgr_end_spell(car.id,'left');end if;
  perform public.cw_promote_season(car.id,sid,o.from_club);spell:=public.mgr_start_spell(car.id,o.from_club);
  update public.cw_coach set monthly_salary=o.salary,contract_until=(w.today+make_interval(years=>o.contract_years))::date,promised_budget=o.budget_guarantee where career_id=car.id;
  update public.cw_clubs set distress_since=case when financial_risk>=75 then w.today else distress_since end where career_id=car.id and club_id=o.from_club;
  insert into public.cw_coach_contracts(career_id,spell_id,club_id,starts_on,expires_on,monthly_salary)
   values(car.id,spell,o.from_club,w.today,(w.today+make_interval(years=>o.contract_years))::date,o.salary);
  if o.bonus_coins>0 then perform public.cw_cash(car.id,o.from_club,-o.bonus_coins,'coach_signing',o.id::text,'Luvas do treinador');perform public.econ_apply(car.id,'coins',o.bonus_coins,'coach_signing',o.id::text);end if;
  update public.season_offers set status='accepted',responded_at=now() where id=o.id;
  update public.season_offers set status='expired',responded_at=now() where career_id=car.id and kind='coach' and status='pending';
  perform public.cw_news_add(car.id,'coach-hired:'||spell,'job',public.mgr_club_name(o.from_club)||' anuncia novo treinador','Contrato por '||o.contract_years||' anos. A temporada e os resultados existentes continuam.',98,o.from_club);
 else update public.season_offers set status='declined',responded_at=now() where id=o.id;end if;
 return jsonb_build_object('ok',true,'accepted',p_accept,'club_id',o.from_club);
end $$;
create or replace function public.mgr_new_season(p_career uuid)
returns uuid language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare w public.cw_world;c public.mgr_coach;old_s public.career_seasons;sid uuid;yr int;
begin
 if not exists(select 1 from public.cw_world where career_id=p_career) then return public.mgr_new_season_before_world(p_career);end if;
 select * into w from public.cw_world where career_id=p_career;select * into c from public.mgr_coach where career_id=p_career;
 select * into old_s from public.career_seasons where id=w.primary_season;
 if old_s.status='active' then raise exception 'A temporada atual está em andamento';end if;
 yr:=greatest(old_s.year+1,public.cw_year(old_s.region,w.today));
 if w.today<public.cw_start(old_s.region,yr) then raise exception 'Avance os dias até o início da próxima temporada';end if;
 sid:=public.cw_create_region(p_career,old_s.region,yr);perform public.cw_promote_season(p_career,sid,c.club_id);
 if c.status='employed' then
  perform public.mgr_create_objectives(p_career,sid,c.spell_id,c.club_id);
  update public.mgr_coach set board_confidence=round(board_confidence+(62-board_confidence)*.5,2),fan_mood=round(fan_mood+(60-fan_mood)*.5,2),warned=0,fan_warned=0 where career_id=p_career;
 end if;return sid;
end $$;
create or replace function public.mgr_season_next()
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;sid uuid;
begin car:=public.mgr_lock();sid:=public.mgr_new_season(car.id);return jsonb_build_object('ok',true,'season_id',sid);end $$;
create or replace function public.career_world_status()
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;own text;w public.cw_world;
begin
 car:=public.mgr_lock();select * into w from public.cw_world where career_id=car.id;select club_id into own from public.mgr_coach where career_id=car.id and status='employed';
 return to_jsonb(w)-'career_id'||jsonb_build_object('coach',(select to_jsonb(c)-'career_id' from public.cw_coach c where career_id=car.id),
 'club',(select to_jsonb(c)-'career_id'||jsonb_build_object('payroll',public.cw_payroll(car.id,own),'reserved',public.cw_reserved(car.id,own),'available',public.cw_available_budget(car.id,own),'window_open',public.cw_window_open(public.cw_region(own),w.today),'next_window',public.cw_next_window(public.cw_region(own),w.today)) from public.cw_clubs c where career_id=car.id and club_id=own),
 'seasons',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select ws.region,ws.year,s.status,ws.season_id,ws.starts_on,ws.ends_on from public.cw_seasons ws join public.career_seasons s on s.id=ws.season_id where ws.career_id=car.id order by ws.starts_on desc limit 8)x),
 'due_matches',(select count(*) from public.cw_fixture_dates fd join public.season_fixtures f on f.id=fd.fixture_id where fd.career_id=car.id and fd.due_on<=w.today and f.status='pending' and not(f.season_id=w.primary_season and own is not null and own in(f.home_club,f.away_club))),
 'news_unread',(select count(*) from public.cw_news where career_id=car.id and not read));
end $$;
create or replace function public.mgr_hub()
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare h jsonb;w jsonb;d date;car uuid;
begin
 h:=public.mgr_hub_before_world();w:=public.career_world_status();car:=(h#>>'{career,id}')::uuid;
 if h#>>'{next_event,fixture_id}' is not null then
  select due_on into d from public.cw_fixture_dates where fixture_id=(h#>>'{next_event,fixture_id}')::bigint;
  h:=jsonb_set(h,'{next_event}',h->'next_event'||jsonb_build_object('scheduled_on',d,'days_until',d-(w->>'today')::date));
 end if;
 h:=jsonb_set(h,'{offers}',(select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'club_id',o.from_club,'pitch',o.pitch,'context',o.context,'bonus_coins',o.bonus_coins,'salary',o.salary,'contract_years',o.contract_years,'budget_guarantee',o.budget_guarantee,'expires_on',o.expires_on,'days_left',o.expires_on-(w->>'today')::date,'negotiation_round',o.negotiation_round)),'[]') from public.season_offers o where career_id=car and kind='coach' and status='pending'));
 return h||jsonb_build_object('career_world_version',1,'world',w);
end $$;
-- Owned global search. Catalog is shared, assignments/contracts/values are per career.
drop function if exists public.career_player_search(text,text,text,text,bigint,int);
create or replace function public.career_player_search(p_query text default '',p_position text default '',p_region text default '',p_club text default '',p_max_value bigint default null,p_page int default 0,p_country text default '')
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;own text;
begin
 car:=public.mgr_lock();select club_id into own from public.mgr_coach where career_id=car.id;
 return(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(
  select sp.id,sp.full_name as name,sp.short_name,sp.position,mp.club_id,sp.nationality,round(pr.rating) as overall,round(mp.condition) as condition,
   cp.age_at_start+floor(((select today-started_on from public.cw_world where career_id=car.id))/365.25)::int as age,cp.age_estimated,cp.potential,cp.morale,cp.promised_role,cp.transfer_requested,
   public.cw_player_value(car.id,sp.id) as value,ct.monthly_salary,ct.expires_on,ct.role,ct.arrears,
   coalesce((select sum(st.minutes) from public.mgr_player_stats st join public.career_seasons ss on ss.id=st.season_id where ss.career_id=car.id and ss.status='active' and st.player_id=sp.id),0) as minutes
  from public.mgr_players mp join public.sim_players sp on sp.id=mp.player_id join public.sim_player_pos_ratings pr on pr.player_id=sp.id and pr.pos=sp.position
  join public.cw_players cp on cp.career_id=mp.career_id and cp.player_id=mp.player_id left join public.cw_contracts ct on ct.career_id=car.id and ct.player_id=sp.id and ct.status='active'
  where mp.career_id=car.id and sp.active and (coalesce(p_query,'')='' or sp.full_name ilike '%'||left(p_query,60)||'%')
   and (coalesce(p_country,'')='' or (select country from public.sim_clubs sc where sc.id=mp.club_id)=upper(p_country))
   and (coalesce(p_position,'')='' or sp.position=p_position)
   and (coalesce(p_region,'')='' or public.cw_region(mp.club_id)=p_region or(p_region='free' and mp.club_id is null))
   and (coalesce(p_club,'')='' or mp.club_id=case when p_club='mine' then own else p_club end)
   and (p_max_value is null or public.cw_player_value(car.id,sp.id)<=p_max_value)
  order by pr.rating desc,sp.id limit 30 offset least(greatest(coalesce(p_page,0),0),200)*30)x);
end $$;
create or replace function public.career_negotiations()
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;own text;
begin
 car:=public.mgr_lock();select club_id into own from public.mgr_coach where career_id=car.id;
 return(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select n.id,n.player_id,public.mgr_player_name(n.player_id) as player_name,n.seller_club,n.buyer_club,n.status,n.initiator,n.fee,n.installments,n.performance_bonus,n.monthly_salary,n.contract_years,n.signing_bonus,n.role,n.appearance_bonus,n.goal_bonus,n.created_on,n.reply_on,n.expires_on,n.register_on,n.round_no,n.response,n.valuation,
  (select coalesce(jsonb_agg(jsonb_build_object('date',h.on_date,'actor',h.actor,'state',h.state,'explanation',h.explanation,'terms',h.terms) order by h.id),'[]') from public.cw_offer_history h where h.negotiation_id=n.id and h.career_id=car.id) as history
 from public.cw_negotiations n where n.career_id=car.id and own in(n.buyer_club,n.seller_club) order by n.created_on desc,n.id limit 60)x);
end $$;
create or replace function public.career_news(p_before bigint default null)
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;own text;
begin car:=public.mgr_lock();select club_id into own from public.mgr_coach where career_id=car.id;
 return(select coalesce(jsonb_agg(to_jsonb(x) order by x.on_date desc,(x.club_id=own) desc nulls last,x.priority desc,x.id desc),'[]') from(select n.id,n.on_date,n.kind,n.priority,n.title,n.body,n.club_id,n.player_id,n.season_id,n.metadata,n.read from public.cw_news n where n.career_id=car.id and (p_before is null or n.id<p_before) order by n.id desc limit 40)x);
end $$;
create or replace function public.career_news_read(p_ids bigint[])
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;
begin car:=public.mgr_lock();update public.cw_news set read=true where career_id=car.id and id=any(p_ids);return jsonb_build_object('ok',true);end $$;
create or replace function public.career_finance_history()
returns jsonb language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare car public.careers;own text;
begin car:=public.mgr_lock();select club_id into own from public.mgr_coach where career_id=car.id;
 return(select coalesce(jsonb_agg(to_jsonb(x) order by id desc),'[]') from(select id,on_date,kind,amount,cash_after,description,metadata from public.cw_finance where career_id=car.id and club_id=own order by id desc limit 60)x);end $$;

create or replace function public.mgr_history()
returns jsonb language plpgsql security definer set search_path = public as $$
#variable_conflict use_column
declare
  v_car public.careers;
  v_c   public.mgr_coach;
begin
  v_car := public.mgr_lock();
  select * into v_c from public.mgr_coach where career_id = v_car.id;
  return jsonb_build_object(
    'coach', jsonb_build_object('reputation', round(v_c.reputation, 1), 'matches', v_c.matches, 'wins', v_c.wins, 'draws', v_c.draws,
      'losses', v_c.losses, 'gf', v_c.gf, 'ga', v_c.ga, 'titles', v_c.titles, 'fired_count', v_c.fired_count, 'seasons', v_c.seasons,
      'status', v_c.status, 'club_id', v_c.club_id),
    'spells', (select coalesce(jsonb_agg(jsonb_build_object('id', sp.id, 'club_id', sp.club_id, 'current', sp.id = v_c.spell_id,
        'started_year', sp.started_year, 'started_day', sp.started_day, 'started_season', sp.started_season,
        'ended_year', sp.ended_year, 'ended_day', sp.ended_day, 'end_reason', sp.end_reason,
        'matches', sp.matches, 'wins', sp.wins, 'draws', sp.draws, 'losses', sp.losses, 'gf', sp.gf, 'ga', sp.ga, 'titles', sp.titles)
        order by sp.created_at desc), '[]'::jsonb) from public.mgr_spells sp where sp.career_id = v_car.id),
    'seasons', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'year', s.year, 'region', s.region, 'season_no', s.season_no, 'status', s.status,
        'club_id', s.club_id, 'matches', s.matches, 'wins', s.wins, 'draws', s.draws, 'losses', s.losses,
        'xp_earned', s.xp_earned, 'coins_earned', s.coins_earned, 'summary', s.summary,
        'final_tables', (select coalesce(jsonb_object_agg(ft.competition_id,ft.standings),'{}'::jsonb) from public.season_final_tables ft where ft.season_id=s.id),
        'clubs', (select coalesce(jsonb_agg(distinct f.coach_club), '[]'::jsonb) from public.season_fixtures f where f.season_id = s.id and f.player_match),
        'objectives', (select coalesce(jsonb_agg(jsonb_build_object('label', o.label, 'status', o.status, 'club_id', o.club_id) order by o.priority desc), '[]'::jsonb)
                         from public.mgr_objectives o where o.season_id = s.id))
        order by s.season_no desc), '[]'::jsonb)
        from public.career_seasons s where s.career_id = v_car.id and (s.mode = 'coach' or s.was_coached)));
end;
$$;
do $acl$ declare fn record;begin
 for fn in select p.oid::regprocedure as sig,p.proname as name from pg_proc p join pg_namespace ns on ns.oid=p.pronamespace
 where ns.nspname='public' and (p.proname like 'cw\_%' escape '\' or p.proname like '%before_world%' or p.proname like 'career\_%' escape '\') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',fn.sig);
  if fn.name in('career_club_invest','career_transfer_bid','career_transfer_respond','career_player_offer','career_contract_renew','career_player_role','career_job_negotiate','career_coach_renew','career_world_advance','career_world_status','career_player_search','career_negotiations','career_news','career_news_read','career_finance_history') then execute format('grant execute on function %s to authenticated',fn.sig);end if;
 end loop;
end $acl$;
revoke all on function public.mgr_lock(),public.mgr_sync_base_cards(uuid),public.mgr_match_create(bigint,uuid,char,jsonb),public.sim_play_round(uuid,text,text,int),public.mgr_day_tick(uuid,uuid),public.mgr_new_season(uuid),public.mgr_fire(uuid,text),public.mgr_end_spell(uuid,text),public.mgr_make_offer(uuid,uuid,int,boolean,boolean) from public,anon,authenticated,service_role;
revoke all on function public.mgr_hub(),public.mgr_match_start(),public.mgr_advance(boolean),public.mgr_offer_respond(uuid,boolean),public.mgr_season_next(),public.mgr_history(),public.sim_next_event(uuid,text),public.mgr_offer_region_ok(uuid,text) from public,anon,service_role;
grant execute on function public.mgr_hub(),public.mgr_match_start(),public.mgr_advance(boolean),public.mgr_offer_respond(uuid,boolean),public.mgr_season_next(),public.mgr_history() to authenticated;
notify pgrst,'reload schema';

set local lock_timeout='5s';
select pg_advisory_xact_lock(hashtext('career-calendar-entry-v2'));
alter table public.cw_world add column if not exists parallel_entry_aligned boolean not null default false;
alter table public.cw_seasons add column if not exists calendar_shift int not null default 0 check(calendar_shift>=0);
-- The deployment itself never changes progress or existing match dates.
create temp table cw_entry_results on commit drop as select id,to_jsonb(f) as original from public.season_fixtures f where status='played';
create temp table cw_entry_live on commit drop as select fixture_id,to_jsonb(m) as original from public.mgr_matches m where status='live';
create temp table cw_entry_wallet on commit drop as select id,to_jsonb(c) as original from public.careers c;
-- Lazily repair only unplayed foreign schedules. No catch-up results are invented.
create or replace function public.cw_schedule(p_season uuid)
returns int language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare n int:=0;r record;chosen date;
begin
 for r in
 select f.id,f.season_id,f.home_club,f.away_club,s.career_id,s.ends_on+s.calendar_shift as ends_on,
 least(s.ends_on+s.calendar_shift,greatest(s.starts_on+s.calendar_shift,s.starts_on+s.calendar_shift+case
  when public.sim_phase(f.competition_id,f.stage)->>'type'='league' then 14+(f.round_no-1)*greatest(1,330/greatest(coalesce((c.rules->>'calendar_rounds')::int,38)-1,1))
  when public.sim_phase(f.competition_id,f.stage)->>'type' in('groups','group','swiss') then 60+(f.round_no-1)*18
  when c.kind='continental' then 210+greatest(0,public.sim_phase_index(f.competition_id,f.stage)-2)*28+greatest(coalesce(f.leg,1)-1,0)*7
  else 90+greatest(0,public.sim_phase_index(f.competition_id,f.stage)-1)*50+greatest(coalesce(f.leg,1)-1,0)*7 end)) as proposed
 from public.season_fixtures f join public.cw_seasons s on s.season_id=f.season_id join public.sim_competitions c on c.id=f.competition_id
 where f.season_id=p_season and f.status='pending' and not exists(select 1 from public.cw_fixture_dates d where d.fixture_id=f.id)
 order by exists(select 1 from public.mgr_matches m where m.fixture_id=f.id and m.status='live' and m.user_side is not null) desc,proposed,c.sort_order,f.id loop
  chosen:=case when exists(select 1 from public.mgr_matches m where m.fixture_id=r.id and m.status='live' and m.user_side is not null) then (select today from public.cw_world where career_id=r.career_id) else greatest(r.proposed,(select today from public.cw_world where career_id=r.career_id)) end;
  while exists(select 1 from public.cw_club_dates d where d.career_id=r.career_id and d.club_id in(r.home_club,r.away_club) and d.due_on between chosen-1 and chosen+1) loop
   chosen:=chosen+1;
   if chosen>r.ends_on+45 then raise exception 'Calendário sem data válida';end if;
  end loop;
  insert into public.cw_fixture_dates values(r.id,r.season_id,r.career_id,chosen);
  insert into public.cw_club_dates values(r.career_id,r.home_club,chosen,r.id),(r.career_id,r.away_club,chosen,r.id);
  n:=n+1;
 end loop;
 return n;
end $$;
create or replace function public.cw_create_region(p_career uuid,p_region text,p_year int)
returns uuid language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare sid uuid;seq int;co record;phase jsonb;starts date;
begin
 perform 1 from public.careers where id=p_career for update;
 select season_id into sid from public.cw_seasons where career_id=p_career and region=p_region and year=p_year;
 if sid is not null then return sid;end if;
 -- Reuse legacy regional history; a completed year must never be generated twice.
 select cs.id into sid from public.career_seasons cs where cs.career_id=p_career and cs.region=p_region and cs.year=p_year and cs.mode in('coach','world') order by cs.season_no desc limit 1;
 if sid is not null then
  starts:=public.cw_start(p_region,p_year);
  insert into public.cw_seasons(career_id,region,year,season_id,starts_on,ends_on) values(p_career,p_region,p_year,sid,starts,(starts+interval '1 year - 1 day')::date);
  update public.career_seasons set was_coached=was_coached or mode='coach' where id=sid;
  if(select status from public.career_seasons where id=sid)='active' then perform public.cw_schedule(sid);end if;
  return sid;
 end if;
 if not exists(select 1 from public.sim_competitions where region=p_region and active) then raise exception 'Região sem competições cadastradas';end if;
 select coalesce(max(season_no),0)+1 into seq from public.career_seasons where career_id=p_career;
 insert into public.career_seasons(career_id,season_no,year,club_id,region,mode,day_no)
 values(p_career,seq,p_year,null,p_region,'world',coalesce((select elapsed_days from public.cw_world where career_id=p_career),0)) returning id into sid;
 perform public.mgr_init_world(p_career);perform public.cw_initialize_finances(p_career);
 starts:=public.cw_start(p_region,p_year);
 insert into public.cw_seasons(career_id,region,year,season_id,starts_on,ends_on,calendar_shift) values(p_career,p_region,p_year,sid,starts,(starts+interval '1 year - 1 day')::date,greatest(0,(select today from public.cw_world where career_id=p_career)-starts));
 perform public.sim_participants_build(sid);
 for co in select * from public.sim_competitions where region=p_region and active order by sort_order loop
  phase:=public.sim_phase_at(co.id,1);
  insert into public.season_competitions(season_id,competition_id,stage) values(sid,co.id,phase->>'id');
  perform public.sim_phase_create(sid,co.id,phase->>'id',null);
 end loop;
 perform public.cw_schedule(sid);return sid;
end $$;
create or replace function public.cw_align_parallel_entry(p_career uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare w public.cw_world;s record;first_due date;delta int;
begin
 perform 1 from public.careers where id=p_career for update;
 select * into w from public.cw_world where career_id=p_career for update;
 if not found or w.parallel_entry_aligned then return;end if;
 -- Preserve even the dates of an interrupted interactive match.
 if exists(select 1 from public.mgr_matches where career_id=p_career and status='live' and user_side is not null) then return;end if;
 for s in select ws.season_id from public.cw_seasons ws join public.career_seasons cs on cs.id=ws.season_id
  where ws.career_id=p_career and ws.season_id<>w.primary_season and cs.status='active' loop
  select min(fd.due_on) into first_due from public.cw_fixture_dates fd join public.season_fixtures f on f.id=fd.fixture_id
   where fd.season_id=s.season_id and f.status='pending';
  if first_due<w.today then
   delta:=w.today+2-first_due;
   -- Remove/reinsert reservations so positive shifts cannot hit their own old unique keys.
   delete from public.cw_club_dates cd using public.season_fixtures f where cd.fixture_id=f.id and f.season_id=s.season_id and f.status='pending';
   update public.cw_fixture_dates fd set due_on=due_on+delta from public.season_fixtures f
    where fd.fixture_id=f.id and f.season_id=s.season_id and f.status='pending';
   update public.cw_seasons set calendar_shift=calendar_shift+delta where season_id=s.season_id;
   insert into public.cw_club_dates(career_id,club_id,due_on,fixture_id)
    select fd.career_id,c.club_id,fd.due_on,f.id from public.season_fixtures f join public.cw_fixture_dates fd on fd.fixture_id=f.id
    cross join lateral(values(f.home_club),(f.away_club))c(club_id) where f.season_id=s.season_id and f.status='pending';
  end if;
 end loop;
 update public.cw_world set parallel_entry_aligned=true,needs_sync=exists(
  select 1 from public.cw_fixture_dates fd join public.season_fixtures f on f.id=fd.fixture_id join public.career_seasons cs on cs.id=f.season_id
  left join public.mgr_coach co on co.career_id=fd.career_id and co.status='employed'
  where fd.career_id=p_career and cs.status='active' and f.status='pending' and fd.due_on<=w.today
  and not(f.season_id=w.primary_season and co.club_id is not null and co.club_id in(f.home_club,f.away_club)))
 where career_id=p_career;
end $$;
create or replace function public.cw_ensure(p_career uuid)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare s public.career_seasons;starts date;current_day date;v_region text;sid uuid;
begin
 perform 1 from public.careers where id=p_career for update;
 if exists(select 1 from public.cw_world where career_id=p_career) then perform public.cw_align_parallel_entry(p_career);return;end if;
 select * into s from public.career_seasons where career_id=p_career and mode='coach' order by season_no desc limit 1;
 if not found then raise exception 'Carreira de treinador não inicializada';end if;
 starts:=public.cw_start(s.region,s.year);
 current_day:=case when s.status='finished' then(starts+interval '1 year - 1 day')::date else least((starts+interval '1 year - 1 day')::date,starts+s.day_no*3) end;
 -- Legacy careers advanced regions sequentially. Do not move the global date behind an already completed regional year.
 select greatest(current_day,coalesce(max((public.cw_start(cs.region,cs.year)+interval '1 year - 1 day')::date),current_day)) into current_day
 from public.career_seasons cs where cs.career_id=p_career and cs.mode='coach' and (cs.status='finished' or(cs.status='archived' and not exists(select 1 from public.season_fixtures fx where fx.season_id=cs.id and fx.status='pending')));
 insert into public.cw_world(career_id,today,started_on,elapsed_days,primary_season) values(p_career,current_day,current_day,s.day_no,s.id) on conflict do nothing;
 insert into public.cw_coach(career_id,monthly_salary,contract_until) select p_career,round(70+reputation*3)::bigint,(current_day+interval '2years')::date from public.mgr_coach where career_id=p_career on conflict do nothing;
 insert into public.cw_seasons(career_id,region,year,season_id,starts_on,ends_on) values(p_career,s.region,s.year,s.id,starts,(starts+interval '1 year - 1 day')::date) on conflict do nothing;
 update public.career_seasons set was_coached=true where id=s.id;
 perform public.mgr_init_world(p_career);
 perform public.cw_initialize_finances(p_career);
 perform public.cw_schedule(s.id);
 for v_region in select distinct comp.region from public.sim_competitions comp where comp.active and comp.region<>s.region loop
  sid:=public.cw_create_region(p_career,v_region,public.cw_year(v_region,current_day));
  if(select status from public.career_seasons where id=sid)<>'active' then sid:=public.cw_create_region(p_career,v_region,public.cw_year(v_region,current_day)+1);end if;
 end loop;
 update public.season_offers set expires_on=current_day+greatest(1,coalesce(expires_day-s.day_no,7)),
 salary=coalesce(salary,150),contract_years=coalesce(contract_years,2),budget_guarantee=coalesce(budget_guarantee,0)
 where career_id=p_career and status='pending' and kind='coach' and expires_on is null;
 perform public.cw_news_add(p_career,'world:created','world','O mundo do futebol está em movimento',
 'Brasil e Europa agora seguem calendários próprios na sua carreira. Contratos, finanças e notícias evoluem com os dias.',65,s.club_id);
 perform public.cw_align_parallel_entry(p_career);
end $$;

revoke all on function public.cw_schedule(uuid),public.cw_create_region(uuid,text,int),public.cw_align_parallel_entry(uuid),public.cw_ensure(uuid) from public,anon,authenticated,service_role;
do $preserved$ begin
 if exists(select 1 from cw_entry_results b left join public.season_fixtures f using(id) where b.original is distinct from to_jsonb(f)) then raise exception 'Calendar deployment changed a played result';end if;
 if exists(select 1 from cw_entry_live b left join public.mgr_matches m using(fixture_id) where b.original is distinct from to_jsonb(m)) then raise exception 'Calendar deployment changed a live match';end if;
 if exists(select 1 from cw_entry_wallet b left join public.careers c using(id) where b.original is distinct from to_jsonb(c)) then raise exception 'Calendar deployment changed a user wallet';end if;
end $preserved$;
do $preserved$ begin
 if exists(select 1 from cw_protected_wallet b left join public.careers c using(id) where b.original is distinct from to_jsonb(c)) then raise exception 'A implantação alterou uma carreira existente';end if;
 if exists(select 1 from cw_protected_results b left join public.season_fixtures f using(id) where b.original is distinct from to_jsonb(f)) then raise exception 'A implantação alterou um resultado realizado';end if;
 if exists(select 1 from cw_protected_live b left join public.mgr_matches m using(fixture_id) where b.original is distinct from to_jsonb(m)) then raise exception 'A implantação alterou uma partida ao vivo';end if;
end $preserved$;
commit;
